(window.WCD=window.WCD||[]).push(["marques",[["Q481778",1,"tech","Acer","C","Acer Inc. ou Acer Incorporated est un constructeur informatique taïwanais spécialisé dans la recherche et le développement, la conception, la production et la vente de produits informatiques fondé par Stan Shih.","Acer Inc.","fr:Acer_(entreprise)","c:4/47/Acer_Building_in_Oriental_Science_Park_right-front.jpg"],["Q11463",3,"tech","Adobe","PC","Adobe Inc. ou Adobe, anciennement Adobe Systems, est une multinationale américaine.","Adobe Inc.","fr:Adobe_(entreprise)","c:3/35/Adobe_World_Headquarters.jpg"],["Q63327",4,"tech","Airbnb","R","Airbnb est une multinationale américaine fondée en 2008 par Brian Chesky, Joe Gebbia et Nathan Blecharczyk.",null,"fr:Airbnb","c:2/25/888_Brannan%2C_San_Francisco%2C_2016.jpg",{"cats":["marques","web"]}],["Q1359568",5,"tech","Alibaba Group","PC","Alibaba Group est une société chinoise cotée en bourse qui tire principalement ses revenus de ses activités sur Internet, dont un marché public destiné à faciliter les échanges entre entreprises, des plateformes de paiements et de ventes au détail, un moteur de recherche pour le magasinage et des services de cloud computing. Son activité est proche de celle d'Amazon, mais Amazon génère des revenus plus élevés.",111,"fr:Alibaba_Group","c:c/cc/Alibaba_Group_provisional_office_at_Xiong%27an_%2820180503164635%29.jpg",{"cats":["marques","web"]}],["Q3884",6,"tech","Amazon","L","Amazon, officiellement Amazon.com, Inc., est une multinationale américaine basée à Seattle, dans l'État de Washington.",null,"fr:Amazon","c:0/0c/Seattle_%28February_2022%29_-_063.jpg",{"cats":["marques","sciences","web"]}],["Q128896",7,"tech","AMD","R","Advanced Micro Devices est un fabricant américain de semi-conducteurs, microprocesseurs et cartes graphiques basé à Santa Clara. La compagnie est fondée le 1er mai 1969 par un groupe d'ingénieurs et de dirigeants de Fairchild Semiconductor. Les cofondateurs d'AMD sont Jerry Sanders, Edwin Turney, John Carey, Sven Simonsen, Jack Gifford, Frank Botte, Jim Giles et Larry Stenger. La flèche du logotype de la compagnie dirigée vers la droite symbolise sa croissance dans le « droit chemin ».",115,"fr:Advanced_Micro_Devices","c:1/11/2485_Augustine_Drive_headquarters_in_Santa_Clara%2C_California.jpg"],["Q116758847",8,"tech","Anthropic","L","Anthropic est une entreprise américaine d'intelligence artificielle basée à San Francisco. Fondée en 2021 par d'anciens membres d'OpenAI, l'entreprise a pour PDG Dario Amodei et pour présidente Daniela Amodei.","Anthropic est une entreprise américaine d'intelligence artificielle basée à San Francisco.","fr:Anthropic","https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Anthropic_logo.svg/330px-Anthropic_logo.svg.png"],["Q312",9,"tech","Apple","E","Apple Inc. est une entreprise multinationale américaine qui crée et commercialise des produits électroniques grand public, des ordinateurs personnels et des logiciels. La firme fait partie des géants du Web, appelés GAFAM. Parmi les produits les plus connus de l'entreprise se trouvent les Macintosh, l'iPod, l'iPhone et l'iPad, l'Apple Watch, le lecteur multimédia iTunes, le service de streaming Apple Music ou des logiciels à destination des professionnels tels que Final Cut Pro, Logic Pro ou encore FileMaker Pro,…","Apple Inc.","fr:Apple","c:5/5a/Aerial_view_of_Apple_Park_dllu.jpg",{"cats":["marques","sciences"]}],["Q296782",10,"tech","ARM","C","Arm Limited est une société britannique spécialisée dans le développement de processeurs d'architecture 32 bits et d'architecture 64 bits de type RISC. Filiale de la société holding d'investissement japonaise SoftBank depuis 2016, ARM développe également un grand nombre de blocs de propriété intellectuelle. ARM est désormais présent dans le monde entier et son siège historique se situe à Cambridge.",114,"fr:ARM_(entreprise)","c:8/89/ARM-Cambridge.jpg"],["Q152864",11,"tech","Asus","PC","ASUSTeK Computer Inc., en forme courte Asus, est une entreprise taïwanaise qui produit des cartes mères, des cartes graphiques, des lecteurs optiques, des assistants personnels, des ordinateurs portables, des ordinateurs de bureau, des périphériques réseau, des téléphones portables, des boîtiers et des systèmes de refroidissement d’ordinateurs.",115,"fr:Asus","c:9/91/ASUSTeK_Computer_headquarters_20150711.jpg"],["Q1961036",12,"tech","Beats Electronics","C","Beats Electronics Ttc, couramment appelée Beats by Dre, est une marque de casques audio, d'écouteurs et de haut-parleurs haut de gamme créée en 2006 par le producteur américain Dr. Dre et Jimmy Iovine, président de la maison de disques IGA. En 2014, Apple acquiert l'entreprise pour 3 milliards de dollars.",106,"fr:Beats_Electronics","https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Beats_Electronics_logo.svg/330px-Beats_Electronics_logo.svg.png"],["Q2905238",13,"tech","BlaBlaCar","C","BlaBlaCar est une marque et une plateforme communautaire de mobilité développée par la société française Comuto.",null,"fr:BlaBlaCar","c:a/ae/Blablacar_nalepka_FR.JPG",{"cats":["marques","web"]}],["Q502121",14,"tech","BlackBerry","PC","BlackBerry Limited, anciennement Research In Motion Limited, est une entreprise canadienne spécialisée dans les communications sécurisées et l'Internet des objets. Elle était à l'origine spécialisée dans la conception, la fabrication et la commercialisation de solutions sans fil pour le marché de la communication mobile. De plus, elle opérait un système de messagerie électronique sans fil, système dont la partie la plus visible est le BlackBerry.",111,"fr:BlackBerry_(entreprise)","c:f/f0/BlackBerry_Limited_Waterloo_Campus.jpg"],["Q444172",15,"tech","Bolloré","PC","Le groupe Bolloré est une multinationale française spécialisée dans la logistique pétrolière, la communication, le divertissement et l'industrie. En 1822, Nicolas Le Marié fonde les papeteries d'Odet. Son neveu Jean-René Bolloré lui succède en 1861 et substitue son nom à l'entreprise. Son siège social est situé dans la commune d'Ergué-Gabéric, près de Quimper, en Bretagne. Elle est dirigée par Cyrille Bolloré, fils de Vincent Bolloré.",114,"fr:Bolloré","c:5/5e/Tour_France.JPG"],["Q4035313",16,"tech","Booking.com","PC","Booking.com est un site néerlandais qui propose des hébergements dans différents types de locaux allant de l'hôtel au gîte touristique, en passant par l'appartement. Il est décliné en 43 autres langues.",117,"fr:Booking.com","c:5/53/Booking.com_Headquarters2.JPG",{"cats":["marques","web"]}],["Q328568",17,"tech","Bose","C","Bose Corporation est une entreprise américaine d'électronique basée à Framingham dans le Massachusetts, fondée en 1964 par Amar Bose.",118,"fr:Bose_(entreprise)","c:d/d6/Bose_Store.jpg"],["Q581438",18,"tech","Bouygues Telecom","C","Bouygues Telecom est un opérateur de télécommunications français, filiale du groupe Bouygues, lancé commercialement en 1996. Historiquement, l'entreprise est le troisième des quatre opérateurs de téléphonie mobile nationaux français, apparu après Orange et SFR et avant Free Mobile. L'opérateur exploite également un réseau de fourniture d'accès à Internet « fixe » pour les foyers français.",118,"fr:Bouygues_Telecom","c:c/c0/Bouygues_Telecom_Deux-Lions_Tours.jpg"],["Q62621",19,"tech","Canon","PC","Canon Inc. est une entreprise japonaise basée à Tokyo et spécialisée dans les produits optiques, incluant appareils photo, photocopieurs et imprimantes. Le nom officiel japonais de la compagnie est kiyanon.","Canon Inc.","fr:Canon_(entreprise)","c:b/b0/Canon_HQ3.jpg"],["Q115564437",20,"tech","ChatGPT","M","ChatGPT, prononcé en français, est un agent conversationnel d'intelligence artificielle développé par OpenAI. ChatGPT utilise des transformeurs génératifs préentraînés, tels que GPT-5, afin de générer du texte, des images ou des réponses vocales. Il est le 5e site web le plus visité en 2026.","ChatGPT, prononcé en français, est un agent conversationnel d'intelligence artificielle développé par OpenAI.","fr:ChatGPT","https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/ChatGPT-Logo.svg/330px-ChatGPT-Logo.svg.png",{"cats":["marques","sciences","tech","web"]}],["Q173395",21,"tech","Cisco Systems","PC","Cisco Systems est une entreprise informatique américaine spécialisée, à l’origine, dans le matériel de réseau informatique, et depuis 2009 dans les serveurs. Elle s'est depuis largement diversifiée dans les logiciels et notamment la cybersécurité.",109,"fr:Cisco_Systems","https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Cisco_logo_blue_2016.svg/330px-Cisco_logo_blue_2016.svg.png"],["Q769222",22,"tech","Dailymotion","PC","Dailymotion /ˈdeɪliˈmoʊʃən/ est une entreprise française de médias fondée en mars 2005 par les entrepreneurs français Benjamin Bejbaum et Olivier Poitrey, successivement devenue filiale du groupe Orange à partir de 2011, puis rachetée par Vivendi, elle est aujourd'hui transférée au groupe Canal+ à partir de fin 2024. Le réseau Dailymotion publie sur son site web du même nom, un service d'hébergement, de diffusion, de partage et de visionnage de vidéo en ligne destiné au grand public.",117,"fr:Dailymotion","c:e/e5/Dailymotion_HQ%2C_Paris.JPG",{"cats":["marques","web"]}],["Q602243",23,"tech","Deezer","C","Deezer est une plateforme française de distribution numérique dédiée à l'écoute de musique en streaming, lancée en août 2007. Ce service permet l'écoute de musiques et podcasts, issus d'un catalogue négocié avec les labels regroupant plus de 120 millions de titres en 2024.",119,"fr:Deezer","",{"cats":["marques","web"]}],["Q30873",24,"tech","Dell","R","Dell Technologies, Inc est une entreprise américaine troisième plus grand constructeur d'ordinateurs au monde en 2012 derrière Hewlett-Packard et Lenovo. Son siège est basé à Round Rock dans l'État du Texas.",117,"fr:Dell","https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Dell_logo_2016.svg/330px-Dell_logo_2016.svg.png"],["Q22907849",25,"tech","Discord","E","Discord est une application multiplateforme américaine de voix sur IP et de messagerie instantanée. Elle est distribuée gratuitement et développée avec une licence propriétaire.","Discord est une application multiplateforme américaine de voix sur IP et de messagerie instantanée.","fr:Discord","c:7/7e/Pigeon_ex3_discord_bot.png",{"cats":["marques","sciences","web"]}],["Q22248343",26,"tech","Doctolib","PC","Doctolib est une entreprise française fondée en 2013. Elle distribue un service de réservation de rendez-vous médical en ligne destiné aux patients, accessible en France, en Italie, en Allemagne et aux Pays-Bas. Outre cette fonctionnalité, le site web propose des services logiciels aux professionnels de santé.","Doctolib est une entreprise française fondée en 2013.","fr:Doctolib","https://upload.wikimedia.org/wikipedia/fr/thumb/7/7f/Logo-doctolib.svg/330px-Logo-doctolib.svg.png"],["Q621429",27,"tech","Dyson","C","Dyson est une société anglaise d’électroménager, fondée et présidée par James Dyson. Les principaux produits de cette entreprise sont des aspirateurs à séparation cyclonique sans sac, des purificateurs d'air, des ventilateurs, des sèche-cheveux et des sèche-mains.","Dyson est une société anglaise d’électroménager, fondée et présidée par James Dyson.","fr:Dyson","c:e/e5/Dyson_booth%2C_Softex_Taipei_20180429.jpg"],["Q58024",28,"tech","eBay","R","eBay est une entreprise de marché en ligne américaine, connue pour son site web de commerce en ligne créée le 3 septembre 1995 par le Français Pierre Omidyar. Elle est devenue une référence mondiale dans son secteur et un phénomène de société.",111,"fr:EBay","c:c/c6/EBay_headquarters_2018.jpg",{"cats":["marques","web"]}],["Q355",31,"tech","Facebook","M","Facebook est un réseau social créé par Mark Zuckerberg, puis développé par l'entreprise américaine Meta Platforms. Son espace de contenu généré par les utilisateurs est utilisé pour « suivre » des personnes qui y partagent des images et des vidéos courtes, et parfois du texte, ou pour joindre des groupes de discussion. Les utilisateurs se connectent également sur la messagerie instantanée intégrée, Facebook Messenger, pour communiquer en privé.","Facebook est un réseau social créé par Mark Zuckerberg, puis développé par l'entreprise américaine Meta Platforms.","fr:Facebook","c:f/fd/Serviceman_Using_Facebook_MOD_45152905.jpg",{"cats":["marques","sciences","web"]}],["Q5455414",32,"tech","Fitbit","C","Fitbit est une société américaine fondée en 2007 qui conçoit, développe et commercialise des moniteurs d'activité physique et autres objets connectés.",113,"fr:Fitbit","c:9/93/FitbitStand.jpg"],["Q2467627",33,"tech","Free","C","Free, stylisé en free, entreprise filiale du groupe Iliad, est l'un des principaux fournisseurs d'accès à Internet en France. En nombre d'abonnés haut débit fixe, Free vient en deuxième position en 2024, derrière Orange, mais devant Bouygues Telecom et SFR.",117,"fr:Free_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Free_logo.svg/330px-Free_logo.svg.png",{"cats":["marques","web"]}],["Q658789",34,"tech","Garmin","C","Garmin est une entreprise américaine fondée en 1989 par Gary Burrell et Min H. Kao. Elle est spécialisée dans les systèmes de navigation par GPS dans le domaine automobile, l'aviation, la marine ou encore le sport. Elle est connue du grand public pour ses capteurs d'activités.","Garmin est une entreprise américaine fondée en 1989 par Gary Burrell et Min H.","fr:Garmin","c:6/63/Garmin_hq.JPG"],["Q95",35,"tech","Google","L","Google LLC, prononcé en français, est une entreprise américaine de services technologiques et de marketing en ligne fondée en 1998 dans la Silicon Valley, en Californie, par Larry Page et Sergey Brin, créateurs du moteur de recherche Google. La firme développe et distribue de nombreux autres services très populaires. Elle fait partie des géants du Web, appelés GAFAM. Son site web figure dans la liste des sites web les plus visités.",115,"fr:Google","c:3/32/Googleplex_HQ_%28cropped%29.jpg",{"cats":["marques","sciences"]}],["Q733482",36,"tech","GoPro","C","GoPro, anciennement Woodman Labs, est une entreprise américaine fondée en 2002 et basée à San Mateo en Californie.",null,"fr:GoPro","c:0/05/GoPro_Hero_9_Black_-_Front_2.jpg"],["Q21404084",37,"tech","HP Inc.","PC","HP Inc. est l'une des deux entités résultant de la scission le 31 octobre 2015, de la société historique Hewlett-Packard dont le nom était celui de ses deux fondateurs.","HP Inc.","fr:HP_Inc.","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a7/Logo_Hewlett-Packard_%28HP%29_-_2025.svg/330px-Logo_Hewlett-Packard_%28HP%29_-_2025.svg.png"],["Q160120",38,"tech","Huawei","PC","Huawei, officiellement Huawei Technologies Co., Ltd., est une entreprise chinoise fondée en 1987, dont le siège social se trouve à Shenzhen en Chine et qui fournit des solutions dans le secteur des technologies de l'information et de la communication.",118,"fr:Huawei","c:a/a7/HuaweiShenzhen.jpg"],["Q37156",39,"tech","IBM","R","International Business Machines Corporation, connue sous le sigle IBM, est une entreprise multinationale américaine présente dans les domaines du matériel informatique, du logiciel et des services informatiques.",115,"fr:IBM","c:b/b5/IBM_CHQ_-_Oct_2014.jpg",{"cats":["marques","sciences"]}],["Q209330",40,"tech","Instagram","M","Instagram, prononcé en français, parfois désigné par le diminutif Insta, est un réseau social utilisé pour « suivre » des personnes qui y partagent des images et des vidéos courtes, ainsi que pour échanger avec certaines via l'espace de commentaires sous chaque post ou la messagerie instantanée intégrée. Il est créé en octobre 2010 par l'Américain Kevin Systrom et le Brésilien Mike Krieger. Depuis 2012, l'application appartient au groupe américain Meta.",117,"fr:Instagram","https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Instagram_logo_2022.svg/330px-Instagram_logo_2022.svg.png",{"cats":["marques","sciences","web"]}],["Q248",41,"tech","Intel","PC","Intel Corporation est une entreprise américaine fondée en 1968 par Gordon Moore, Robert Noyce et Andrew Grove. Elle est le second fabricant mondial de semi-conducteurs après Samsung si on se fonde sur le chiffre d'affaires. Elle fabrique des microprocesseurs — c'est d'ailleurs elle qui a créé le premier microprocesseur x86 —, des cartes mères, des mémoires flash et des processeurs graphiques notamment.","Intel Corporation est une entreprise américaine fondée en 1968 par Gordon Moore, Robert Noyce et Andrew Grove.","fr:Intel","c:1/13/2200_Mission_College_Boulevard.jpg",{"cats":["marques","sciences"]}],["Q1153754",42,"tech","JBL","C","JBL est une entreprise américaine crée en 1946 par James Bullough Lansing spécialisée dans la fabrication d'enceintes acoustiques et d'écouteurs. Elle fait partie du Groupe Harman, et est, depuis son rachat par le Groupe Samsung en 2016, une filiale de Samsung Electronics.",117,"fr:JBL_(marque)","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/JBL_logo.svg/330px-JBL_logo.svg.png"],["Q3228701",43,"tech","Leboncoin","PC","Leboncoin est un site web français de petites annonces, fondé en 2006 par l'entreprise norvégienne Adevinta, spécialisée dans les petites annonces. La société exploitante porte le nom de LBC France.",108,"fr:Leboncoin","",{"cats":["marques","web"]}],["Q14799",44,"tech","Lenovo","R","Lenovo est une entreprise sino-américaine fabriquant principalement des ordinateurs, téléphones portables, stations de travail, serveurs informatiques et télévisions connectées. Fondée en 1984 par Liu Chuanzhi, la marque s'est fait connaître mondialement en 2005 lorsqu'elle a racheté la division informatique personnelle d'IBM, devenant ainsi le premier constructeur mondial de PC. Son siège opérationnel est situé à Morrisville, et l'entreprise est incorporée à Hong Kong.",118,"fr:Lenovo","c:2/2a/Lenovo_western_headquarters_%2820170707113944%29.jpg"],["Q162345",45,"tech","LG Electronics","C","LG Electronics Inc., anciennement GoldStar jusqu'en 1995, est une multinationale sud-coréenne, filiale de LG Group, dont le siège social se situe dans le quartier de Yeouido-dong, à Séoul. Celle-ci est spécialisée dans l'électroménager et l'électronique grand public. LG Electronics fait partie de LG Corporation et est souvent considérée comme le pilier de LG Corp, aux côtés de LG Chem, la division du groupe dédiée à la chimie et aux batteries.",115,"fr:LG_Electronics","c:3/3c/LG_Twin_Towers%2CBeijing_China.jpg"],["Q213660",46,"tech","LinkedIn","E","LinkedIn est un réseau social professionnel créé en 2003 à Mountain View en Californie.",null,"fr:LinkedIn","c:6/65/LinkedIn_Headquarters_Sunnyvale.jpg",{"cats":["marques","sciences","web"]}],["Q223127",47,"tech","Logitech","C","Logitech, aussi connu sous le nom de Logi, est une entreprise suisse fondée en 1981 à Apples en Suisse, spécialisée dans la production de périphériques informatiques: claviers, souris, trackballs, webcams, haut-parleurs, casques et casques gamings, télécommande universelle, télécommande de présentation.",115,"fr:Logitech","c:e/e2/EPFL_campus_2017.jpg"],["Q489921",48,"tech","Mastercard","PC","Mastercard Incorporated est une entreprise américaine de système de paiement/retrait dont le siège est à Purchase, New York. Jusqu'en 2006, c'était une société coopérative détenue par plus de 25 000 institutions financières. Depuis, elle est une société cotée en Bourse.",118,"fr:Mastercard","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Mastercard_2019_logo.svg/330px-Mastercard_2019_logo.svg.png"],["Q380",49,"tech","Meta","L","Meta ou Meta Platforms, anciennement connue sous le nom de Facebook Inc., est une multinationale américaine fondée en 2004 par Mark Zuckerberg et des camarades de Harvard.",117,"fr:Meta_(entreprise)","c:4/43/Meta_Headquarters_Sign.jpg",{"cats":["marques","sciences"]}],["Q2283",50,"tech","Microsoft","L","Microsoft Corporation est une multinationale informatique et micro-informatique américaine, fondée le 4 avril 1975 par Bill Gates et Paul Allen. La firme fait partie des géants du Web, appelés GAFAM, ainsi que des principales capitalisations boursières du NASDAQ, aux côtés d'Apple et d'Amazon. En 2026, son chiffre d'affaires s'élevait à 331,8 milliards USD pour un bénéfice net de 133,7 milliards USD.",118,"fr:Microsoft","c:3/30/Building92microsoft.jpg",{"cats":["marques","sciences"]}],["Q119718658",51,"tech","Mistral AI","R","Mistral AI est une entreprise française fondée en avril 2023, spécialisée dans l'intelligence artificielle générative. Elle développe de grands modèles de langages open source et propriétaires. Elle a été cofondée par Arthur Mensch, Guillaume Lample et Timothée Lacroix.","Mistral AI est une entreprise française fondée en avril 2023, spécialisée dans l'intelligence artificielle générative.","fr:Mistral_AI","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Mistral_AI_logo_%282025%E2%80%93%29.svg/330px-Mistral_AI_logo_%282025%E2%80%93%29.svg.png"],["Q907311",52,"tech","Netflix","L","Netflix est une entreprise internationale américaine active dans le secteur de l'industrie du divertissement. Fondé en 1997 à Scotts Valley par Reed Hastings et Marc Randolph, le groupe est spécialisé dans la distribution et l'exploitation d'œuvres cinématographiques et télévisuelles, notamment par le biais d'une plateforme destinée au service de vidéo à la demande. Son siège social se situe à Los Gatos en Californie.","Netflix est une entreprise internationale américaine active dans le secteur de l'industrie du divertissement.","fr:Netflix","https://upload.wikimedia.org/wikipedia/en/thumb/3/3c/Netflix_UI_for_Web.png/330px-Netflix_UI_for_Web.png",{"cats":["marques","sciences","web"]}],["Q1218180",53,"tech","Nikon","C","Nikon est le fabricant anciennement appelé Nippon Kogaku KK japonais d'appareils photographiques et d'optiques avec des gammes de produits dans les domaines d'équipements d'imagerie, d'équipements industriels de précision, d'instruments de diagnostic ainsi que des instruments de mesure industriels, lentilles ophtalmiques, jumelles, télescopes, loupes.",119,"fr:Nikon","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Nikon_Logo.svg/330px-Nikon_Logo.svg.png"],["Q1418",55,"tech","Nokia","R","Nokia Corporation est une entreprise multinationale de télécommunications finlandaise fondée en 1865 par Fredrik Idestam et Leo Mechelin. Devenu le premier constructeur mondial de téléphones mobiles en 1998, il le reste jusqu'en 2011 avant de perdre l'année suivante son titre de numéro un mondial au profit de Samsung. Le 3 septembre 2013, Nokia se sépare de sa division « terminaux mobiles », alors en déclin, qui est reprise par Microsoft et recentre son activité sur sa division « réseaux » Nokia Networks.",112,"fr:Nokia","c:5/59/Nokia_headquarters_in_Espoo.jpg"],["Q182477",56,"tech","Nvidia","E","Nvidia Corporation est une société multinationale américaine de technologie basée à Santa Clara et immatriculée dans l'État du Delaware. Il s'agit d'un éditeur de logiciels et d'une entreprise sans usine qui conçoit des processeurs graphiques, des interfaces de programmation d'applications pour la science des données et le calcul intensif, ainsi que des systèmes sur une puce pour les marchés de l'informatique mobile et de l'automobile.",116,"fr:Nvidia","https://upload.wikimedia.org/wikipedia/fr/thumb/4/47/Nvidia_%28logo%29.svg/330px-Nvidia_%28logo%29.svg.png",{"cats":["marques","sciences"]}],["Q16499972",57,"tech","OnePlus","PC","OnePlus est une entreprise chinoise créée en décembre 2013. Basée à Shenzhen dans la province du Guangdong, elle est spécialisée dans la conception, le développement, la construction et la distribution de smartphones et écouteurs.","OnePlus est une entreprise chinoise créée en décembre 2013.","fr:OnePlus","c:6/6d/OnePlus_3.png"],["Q21708200",58,"tech","OpenAI","L","OpenAI, prononcé, est une entreprise américaine d'intelligence artificielle fondée en décembre 2015 à San Francisco en Californie. L'entreprise développe des modèles d'IA générative, en particulier la série GPT de grands modèles de langage. Son lancement de l'agent conversationnel ChatGPT en novembre 2022 déclenche un intérêt mondial pour les chatbots et l'IA générative.",118,"fr:OpenAI","c:3/33/Pioneer_Building%2C_San_Francisco_%282019%29_-1.jpg",{"cats":["marques","sciences","tech"]}],["Q19900",59,"tech","Oracle","E","Oracle est une entreprise américaine créée en 1977 par Larry Ellison. Ses produits phares sont le système de gestion de base de données Oracle Database, le serveur d'applications Oracle Weblogic Server, le progiciel de gestion intégré Oracle E-Business Suite et l'offre de cloud computing Oracle Cloud Infrastructure. En 2019, Oracle était la deuxième plus grande entreprise de logiciels en matière de chiffre d'affaires et de capitalisation boursière.","Oracle est une entreprise américaine créée en 1977 par Larry Ellison.","fr:Oracle_(entreprise)","c:1/12/Oracle_Headquarters_Redwood_Shores.jpg"],["Q1431486",60,"tech","Orange","PC","Orange est une entreprise française de télécommunications présente dans 26 pays.",null,"fr:Orange_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Orange_logo.svg/330px-Orange_logo.svg.png"],["Q53247",61,"tech","Panasonic","R","Panasonic Holdings Corporation est un grand groupe japonais spécialisé dans l'électronique grand public, et pour les professionnels. Il est basé à Kadoma, dans la préfecture d'Osaka, au Japon.",116,"fr:Panasonic","c:0/05/PanasonicHeadquarters.JPG"],["Q1894793",62,"tech","Parrot","C","Parrot, officiellement Parrot Drones, est une entreprise française spécialisée dans la fabrication de drones fondée en 1994. Présente sur le marché des drones grand public, les jouets robotiques et les équipements connectés à partir de 2010, Parrot se recentre en 2017 sur les micro-drones quadricoptères professionnels destinés aux secteurs de la sécurité et de la défense.",118,"fr:Parrot_(entreprise)","c:d/db/YVR7260_%28cropped%29.jpg"],["Q483959",63,"tech","PayPal","R","PayPal est une entreprise américaine de service de paiement en ligne au niveau international.",null,"fr:PayPal","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/PayPal_2024.svg/330px-PayPal_2024.svg.png",{"cats":["marques","web"]}],["Q170416",64,"tech","Philips","R","Koninklijke Philips N.V., plus connu sous le nom de la société Philips, est une société néerlandaise d'électronique, basée à Amsterdam. Elle fait partie des plus grands groupes en matière d’équipement médical au monde.",116,"fr:Philips","c:6/67/HeadPhilips.jpg"],["Q255381",65,"tech","Pinterest","E","Pinterest est un site web américain mélangeant les concepts de réseautage social et de partage de photographies et d'images, lancé en 2010 par Paul Sciarra, Evan Sharp et Ben Silbermann. Il permet à ses utilisateurs de partager leurs centres d'intérêt et passions à travers des albums de photographies glanées sur Internet. Le nom du site est un mot-valise des mots anglais pin et interest signifiant respectivement « épingle » et « intérêt ».",114,"fr:Pinterest","https://upload.wikimedia.org/wikipedia/en/thumb/9/9c/Pinterest_home.png/330px-Pinterest_home.png",{"cats":["marques","sciences","web"]}],["Q1323662",66,"tech","PlayStation","R","PlayStation est une série de consoles de jeux vidéo créée et développée par Sony Interactive Entertainment. La marque est introduite le 3 décembre 1994 au Japon avec le lancement de la console originale PlayStation. Elle se compose désormais de cinq consoles de salon, un centre de médias, un service en ligne, une ligne de contrôleurs, deux ordinateurs de poche, un téléphone, ainsi que plusieurs magazines.","PlayStation est une série de consoles de jeux vidéo créée et développée par Sony Interactive Entertainment.","fr:PlayStation_(marque)",""],["Q2005282",67,"tech","Proximus","C","Proximus est le plus grand opérateur de télécommunications de Belgique, anciennement Belgacom.","","en:Proximus","c:6/6f/Noordstation_buurt_Belgacom.jpg"],["Q544847",68,"tech","Qualcomm","PC","Qualcomm est une entreprise américaine active dans le domaine de la technologie mobile. Elle est spécialisée dans la conception et la mise en place de solutions de télécommunications. Elle est devenue l'une des toutes premières entreprises mondiales dans son domaine, la conception et la commercialisation de processeurs pour téléphones portables. Qualcomm est une entreprise sans usine et est également connue pour avoir développé la technique d'accès multiple par répartition en code.","Qualcomm est une entreprise américaine active dans le domaine de la technologie mobile.","fr:Qualcomm","c:2/25/Qualcomm_headquarters.jpg"],["Q14657870",69,"tech","Qwant","C","Qwant est un moteur de recherche français mis en ligne en février 2013. Qwant déclare garantir la vie privée de ses utilisateurs en évitant de les tracer à des fins publicitaires, de revendre leurs données personnelles à quiconque, et s'engage à être impartial dans l'affichage des résultats.","Qwant est un moteur de recherche français mis en ligne en février 2013.","fr:Qwant","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Pays_Qwant.svg/330px-Pays_Qwant.svg.png",{"cats":["marques","web"]}],["Q1136",70,"tech","Reddit","L","Reddit est un site web communautaire américain de discussion et d’actualités sociales.",null,"fr:Reddit","https://upload.wikimedia.org/wikipedia/en/thumb/d/de/Reddit_screenshot_%28new%29.png/330px-Reddit_screenshot_%28new%29.png",{"cats":["marques","sciences","web"]}],["Q20718",72,"tech","Samsung Electronics","PC","Samsung Electronics est une entreprise sud-coréenne spécialisée dans la fabrication de produits électroniques. C'est une filiale à 100 % du Groupe Samsung, l'un des principaux chaebols coréens. En 2023, elle emploie 270 372 personnes et est la troisième plus importante société technologique dans le monde quant au chiffre d'affaires, derrière Apple et Alphabet, avec un volume d'activité de 234 129 millions de dollars, d'après le classement Fortune Global 500.","Samsung Electronics est une entreprise sud-coréenne spécialisée dans la fabrication de produits électroniques.","fr:Samsung_Electronics","c:e/e2/Samsung_headquarters.jpg",{"cats":["marques","sciences"]}],["Q218765",73,"tech","SFR","C","La Société française du radiotéléphone, ou SFR, est un opérateur de télécommunications français créé le 18 novembre 1987. Devenue filiale du groupe Altice France de Patrick Drahi depuis 2014, SFR est chronologiquement le deuxième des quatre opérateurs de téléphonie nationaux privés français.",115,"fr:SFR","https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/SFR-2022-logo.svg/330px-SFR-2022-logo.svg.png"],["Q107377209",74,"tech","Shein","PC","Shein est un détaillant chinois de mode en ligne pour adultes et enfants, fondé par Xu Yangtian en 2008. La société cible principalement les femmes âgées de 16 ans à 34 ans.","Shein est un détaillant chinois de mode en ligne pour adultes et enfants, fondé par Xu Yangtian en 2008.","fr:Shein_(société)","",{"cats":["marques","web"]}],["Q333618",75,"tech","Snapchat","E","Snapchat, prononcé en français, aussi désigné par le diminutif Snap, est un réseau social utilisé pour échanger des photos et des vidéos courtes et éphémères au format vertical, mais aussi des messages textuels également éphémères. Il est développé par la société américaine Snap Inc. L'application, accessible dès treize ans, touche surtout des 13-35 ans. Elle compte 443 millions d'utilisateurs actifs quotidiens en septembre 2024.",115,"fr:Snapchat","https://upload.wikimedia.org/wikipedia/fr/thumb/7/75/Snapchat.png/330px-Snapchat.png",{"cats":["marques","sciences","web"]}],["Q41187",76,"tech","Sony","R","Sony Group Corporation est une entreprise multinationale japonaise basée dans l'arrondissement de Minato à Tokyo. Elle est active dans différents domaines tels que l'électronique, la téléphonie, l'informatique, le jeu vidéo, la musique, le cinéma et l'audiovisuel en général.","Sony Group Corporation est une entreprise multinationale japonaise basée dans l'arrondissement de Minato à Tokyo.","fr:Sony","c:5/54/Sony_headquarters_%28crop%29.jpg"],["Q689141",78,"tech","Spotify","E","Spotify est un service suédois de streaming musical sous la forme d'un logiciel propriétaire et d'un site web. Cette plateforme de distribution numérique permet une écoute quasi instantanée de fichiers musicaux. Le catalogue peut être parcouru par artiste ou par album et également via une fonctionnalité de liste de lecture personnalisée.","Spotify est un service suédois de streaming musical sous la forme d'un logiciel propriétaire et d'un site web.","fr:Spotify","c:1/10/Spotify_HK_Stockholm.jpg",{"cats":["marques","sciences","web"]}],["Q15616276",79,"tech","Telegram","L","Telegram est une application et un service de messagerie instantanée multiplateforme en freemium hébergé dans un cloud. Le siège social de Telegram est situé à Dubaï.","Telegram est une application et un service de messagerie instantanée multiplateforme en freemium hébergé dans un cloud.","fr:Telegram_(application)","https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Telegram_2019_Logo.svg/330px-Telegram_2019_Logo.svg.png",{"cats":["marques","sciences","web"]}],["Q114258161",80,"tech","Temu","R","Temu est une plateforme de commerce en ligne fondée sur le principe de la place de marché. Elle est exploitée dans plusieurs pays par la société chinoise PDD Holdings Inc., basée à Dublin. Elle propose des produits à prix très bas qui sont principalement expédiés aux clients directement depuis les usines.","Temu est une plateforme de commerce en ligne fondée sur le principe de la place de marché.","fr:Temu_(marché)","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a6/Temu_logo.svg/330px-Temu_logo.svg.png",{"cats":["marques","web"]}],["Q860580",81,"tech","Tencent","R","Tencent Holdings Limited est une entreprise chinoise créée en 1998, spécialisée dans les services Internet et mobiles, jeux vidéo, ainsi que la publicité en ligne. Son siège se situe dans la zone économique spéciale de Shenzhen, dans le district de Nanshan, en république populaire de Chine.",118,"fr:Tencent","c:3/3a/Tencent_binghai_building202012.jpg"],["Q48938223",82,"tech","TikTok","L","TikTok est un réseau social lancé en 2016 où de nombreux influenceurs et créateurs de contenu plus ou moins notoires publient des vidéos très courtes au format vertical. Développée par l'entreprise chinoise ByteDance pour le marché non chinois, l'application accessible en Chine est dénommée Douyin conçue séparément pour respecter les régulations locales sur les données personnelles.",116,"fr:TikTok","c:2/20/TikTok_app.jpg",{"cats":["marques","sciences","web"]}],["Q780442",84,"tech","Uber","R","Uber, anciennement UberCab, est une multinationale américaine centrée autour d'une application mobile de mise en contact d'utilisateurs et principalement de voiture de transport avec chauffeur. Depuis quelques années, Uber est également active dans la livraison à domicile de repas. Elle a été fondée par Garrett Camp et Travis Kalanick. L'entreprise est basée dans la ville californienne de San Francisco, aux États-Unis. Le groupe est coté au New York Stock Exchange.",112,"fr:Uber","c:6/6e/Self_driving_Uber_prototype_in_San_Francisco.jpg",{"cats":["marques","sciences","web"]}],["Q11935495",87,"tech","Vinted","R","Vinted est un marché en ligne communautaire qui permet de vendre, d'acheter, et d'échanger des vêtements et accessoires d'occasion. La société est créée en 2008 à Vilnius en Lituanie par un couple originaire du pays.",119,"fr:Vinted","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Vinted_Logo_2018.svg/330px-Vinted_Logo_2018.svg.png",{"cats":["marques","web"]}],["Q328840",88,"tech","Visa","PC","Visa Inc. est une société américaine indépendante cotée en Bourse. Elle gère l'un des plus grands réseaux de paiement électronique au monde. Elle compte environ 21 500 employés et cadres, selon le rapport annuel fiscal valable pour l'année 2021, déposé le 18 novembre 2021 et transmis à la Securities and Exchange Commission à Washington, organisme fédéral de régulation bancaire et boursière.","Visa Inc.","fr:Visa_(entreprise)","c:5/59/Visa_headquarters_-_August_2025_-_Sarah_Stierch.jpg"],["Q1049511",89,"tech","WhatsApp","L","WhatsApp est une application multiplateforme américaine de messagerie instantanée chiffrée et de voix sur IP. Elle est désormais distribuée gratuitement et développée avec une licence propriétaire. Dans les années 2020, c'est l'une des messageries et plateformes de VoIP les plus populaires au monde.","WhatsApp est une application multiplateforme américaine de messagerie instantanée chiffrée et de voix sur IP.","fr:WhatsApp","https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/WhatsApp_Logo_green.svg/330px-WhatsApp_Logo_green.svg.png",{"cats":["marques","sciences","web"]}],["Q918",90,"tech","X","L","X, nommé Twitter jusqu'au 23 juillet 2023, est un réseau social utilisé comme plateforme de microblogage. Ses utilisateurs y publient des micromessages, anciennement appelés tweets. Depuis 2022, le réseau appartient à l'entreprise d'intelligence artificielle SpaceXAI, elle-même propriété de l'entreprise spatiale SpaceX, ces deux entreprises appartenant à Elon Musk, entrepreneur, homme d'affaires et homme politique de nationalité sud-africaine, canadienne et américaine.","X, nommé Twitter jusqu'au 23 juillet 2023, est un réseau social utilisé comme plateforme de microblogage.","fr:X_(réseau_social)","c:1/1f/A_serviceman_accesses_social_media_channels%2C_using_a_desktop_computer._MOD_45156051.jpg",{"cats":["marques","sciences","web"]}],["Q15281614",91,"tech","Xbox","R","Xbox est une marque vidéoludique créée et appartenant à Microsoft. La marque est principalement connue pour la commercialisation d'une série de consoles de jeux vidéo de salon développées par Microsoft: la Xbox, la Xbox 360, la Xbox One et la Xbox Series, respectivement de la sixième, septième, huitième et neuvième génération de console de jeux vidéo. La marque représente aussi des applications et des services de streaming par le biais de son service Xbox Live.","Xbox est une marque vidéoludique créée et appartenant à Microsoft.","fr:Xbox","https://upload.wikimedia.org/wikipedia/fr/thumb/c/ca/Logo_XBOX_%282026%29.png/330px-Logo_XBOX_%282026%29.png"],["Q1636958",92,"tech","Xiaomi","R","Xiaomi Corporation est une entreprise chinoise d'électronique et d'informatique basée à Pékin et spécialisée dans la téléphonie mobile et l'électronique grand public. En 2023, Xiaomi occupe la troisième place mondiale des ventes de smartphones, derrière Samsung et Apple et s'est diversifiée dans plusieurs domaines dans la fabrication de produits électroniques.",116,"fr:Xiaomi","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Xiaomi_logo_%282021-%29.svg/330px-Xiaomi_logo_%282021-%29.svg.png"],["Q866",93,"tech","YouTube","M","YouTube, prononcé en français ou, est la principale plateforme de vidéos en ligne en Occident, sous forme d'application web et mobile. Les utilisateurs mettent en ligne, regardent en streaming, évaluent, commentent et partagent le contenu, parfois en direct. Son site web figure dans la liste des sites web les plus visités.",119,"fr:YouTube","c:1/18/YouTube_results_screenshot.jpg",{"cats":["marques","sciences","web"]}],["Q17460900",94,"tech","Zoom Video Communications","C","Zoom Video Communications est une société de téléconférence basée à San José, en Californie. Elle fournit la plateforme de visioconférence du même nom, Zoom, qui combine la vidéoconférence, les réunions en ligne, le tchat et la collaboration mobile à l'aide d'applications propriétaires.","Zoom Video Communications est une société de téléconférence basée à San José, en Californie.","fr:Zoom_Video_Communications","c:8/8b/Panitahamsa_Nai_Banya_Kim_holding_speech.jpg"],["Q3895",95,"mode","Adidas","R","Adidas, stylisé adidas, est une firme allemande fondée en 1949 par Adolf Dassler, spécialisée dans la fabrication d'articles de sport, basée à Herzogenaurach en Allemagne.",113,"fr:Adidas","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Adidas_2022_logo.svg/330px-Adidas_2022_logo.svg.png"],["Q404391",96,"mode","Aigle","C","Aigle est une marque française de bottes, chaussures et prêt-à-porter sous laquelle l'entreprise Hutchinson créée en 1853 commercialise initialement ses produits avant que la marque ne devienne en 1994 une entreprise distincte qui appartient désormais à Maus Frères Holding.",116,"fr:Aigle_(entreprise)","c:b/b3/Aigle-mud_022.jpg"],["Q327247",97,"mode","ASICS","R","ASICS ou Asics est un équipementier sportif japonais fondé en 1949 et notamment connu pour ses chaussures de course à pied.",117,"fr:ASICS","c:3/3f/ASICS_Japan_Head_Office_%28Shin-suna%29_outside.jpg"],["Q648458",98,"mode","Birkenstock","C","Birkenstock est une marque allemande de sandales, de claquettes et de chaussures, basée à Neustadt, en Rhénanie-Palatinat.",102,"fr:Birkenstock","c:1/17/St._Katharinen%2C_Birkenstock.jpg"],["Q1068628",99,"mode","Calvin Klein","C","Calvin Klein est une entreprise de prêt-à-porter américaine. L'entreprise, qui est devenue célèbre pour ses lignes de sous-vêtements et de denim de créateurs dans les années 1980. Elle est spécialisée dans le prêt-à-porter grand public pour tous les sexes et tous les groupes d'âge, ainsi que dans les produits en cuir, les accessoires et chaussures de style de vie, l'ameublement, les parfums, lunettes, bijoux et montres dans le segment de prix moyen.","Calvin Klein est une entreprise de prêt-à-porter américaine.","fr:Calvin_Klein_(marque)","c:a/ad/CalvinKleinFairviewMall2.jpg"],["Q2988422",100,"mode","Canada Goose","C","Canada Goose /'kænədə ɡus/ est une marque canadienne de vêtements d'extérieur pour les mois de temps froid. La société a été fondée en 1957 par Sam Tick sous le nom Metro Sportswear Ltd.","Canada Goose /'kænədə ɡus/ est une marque canadienne de vêtements d'extérieur pour les mois de temps froid.","fr:Canada_Goose","c:3/38/Canada_Goose_logo_label.jpg"],["Q414120",101,"mode","Celio","C","Celio est une marque française de prêt-à-porter masculin fondée en 1985, présente dans de nombreux pays.","","fr:Celio_(homonymie)",""],["Q2948688",102,"mode","Champion","C","Champion, parfois appelé Champion U.S.A, est une entreprise américaine spécialisée dans les chaussures, les vêtements et le matériel de sport. Fondée en 1919, son siège social est situé à Winston-Salem en Caroline du Nord. Avant son acquisition par Sara Lee, le siège social de l'entreprise était basé à Rochester.",117,"fr:Champion_(marque)","c:5/56/Champion_Wear_at_Mitsui_Outlet_Park_Osaka-Kadoma.jpg"],["Q319515",103,"mode","Converse","C","Converse est une entreprise fondée en 1908 par Marquis Mills Converse à Malden dans le Massachusetts aux États-Unis, et qui fabrique essentiellement des chaussures de sport.",119,"fr:Converse_(chaussure)","https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Converse_logo.svg/330px-Converse_logo.svg.png"],["Q926699",104,"mode","Crocs","C","Crocs Inc. est une entreprise américaine de fabrication de chaussures créée en 2002 et, par extension, un type de chaussures. La société est cotée en bourse depuis 2006. L'entreprise Crocs a aussitôt réussi le positionnement sur le segment premium.","Crocs Inc.","fr:Crocs","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9f/Crocs.svg/330px-Crocs.svg.png"],["Q3012602",105,"mode","Damart","C","Damart est un groupe de vente par correspondance créé en 1953 par la famille Despature, dont le siège social est situé à Roubaix dans le Nord, en France. Damart est une marque de textile qui commercialise ses vêtements à travers des catalogues, des sites Web et un réseau de plus de 130 magasins en Europe dont 85 en France. Enseigne du groupe Damartex, son siège social se situe également à Roubaix, où l'entreprise a fermé ses usines mais y conserve son centre de recherches et développement.",118,"fr:Damart",""],["Q158285",107,"mode","Diesel","C","‌",null,"fr:Diesel_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Diesel.svg/330px-Diesel.svg.png"],["Q1126126",108,"mode","Dr. Martens","C","Dr. Martens est une entreprise britannique d'origine allemande spécialisée dans les chaussures à semelle coussin d'air.","Dr.","fr:Dr._Martens","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b5/Dr._Martens_Logo.svg/330px-Dr._Martens_Logo.svg.png"],["Q482539",109,"mode","Fila","C","Fila est une marque italienne fondée à Coggiola dans le Piémont en 1911 par les frères Ettore et Giansevero Fila, spécialisée dans les vêtements de sport. Depuis 2007, la marque est une filiale de l'entreprise sud-coréenne Misto Holdings.",113,"fr:Fila","c:e/e4/HK_TST_K11_mall_50_shop_FILA_clothing.JPG"],["Q420822",110,"mode","Gap","C","Gap est un groupe de magasins de vêtements basé à San Francisco aux États-Unis fondé en 1969 par Donald Fisher, car, selon la légende, ce dernier ne trouvait pas de jeans à son goût. Le nom lui a été soufflé par sa femme en référence au « generation gap », ou bien l'écart entre les générations.",116,"fr:Gap_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Gap_logo.svg/330px-Gap_logo.svg.png"],["Q188326",111,"mode","H&M","PC","H&M, sigle de Hennes & Mauritz, est une entreprise et une chaîne de magasins suédoise de prêt-à-porter pour femme, homme et enfant, fondée en 1947 par Erling Persson.",114,"fr:H&M","https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/H%26M-Logo.svg/330px-H%26M-Logo.svg.png"],["Q491627",112,"mode","Hugo Boss","PC","Hugo Boss AG est un groupe international de mode, basé en Allemagne.",null,"fr:Hugo_Boss","c:b/ba/Boss-Zentrale-Metzingen.jpg"],["Q735873",113,"mode","Kappa","C","Kappa est un équipementier sportif italien créé en 1978 à Turin en Italie.",null,"fr:Kappa_(entreprise)","c:3/35/Kappa_store_at_the_Grand_Century_Place_in_Hong_Kong.JPG"],["Q3196299",114,"mode","Kiabi","C","Kiabi est une société de distribution de prêt-à-porter créée en 1978 à Roncq par Patrick Mulliez.",null,"fr:Kiabi","c:6/6f/Web-Kiabi_Englos_9-2021_%C2%A9Barbara_Grossmann-219.jpg"],["Q127962",117,"mode","Levi Strauss & Co.","PC","Levi Strauss & Co., aussi connu sous son diminutif commercial Levi's, est une marque de vêtements américaine connue mondialement pour ses blue-jeans, dont le Levi's 501.",115,"fr:Levi_Strauss_&_Co.","c:6/61/Boutique_Levi%27s_de_Mons_-_fr.jpg"],["Q1548951",118,"mode","Moncler","C","Moncler S.p.A. est une maison de luxe italienne d'origine française fondée en 1952 à Monestier-de-Clermont, spécialisée dans le prêt-à-porter haut de gamme pour l’extérieur, avec son siège installé à Milan. Son identité visuelle distinctive repose sur des symboles emblématiques tels qu’un coq, le monogramme « M », un écusson en feutre, des skis croisés, ainsi qu’une mascotte en forme de canard dessiné.","Moncler S.p.A.","fr:Moncler","c:8/86/Moncler_Vancouver%2C_Canada_%2823652412944%29.jpg"],["Q742988",119,"mode","New Balance","PC","New Balance Athletics est un équipementier sportif américain.",null,"fr:New_Balance","https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/New_Balance_logo.svg/330px-New_Balance_logo.svg.png"],["Q483915",120,"mode","Nike","E","Nike est une société américaine créée en 1968 par Philip Knight et Bill Bowerman. Basée à Beaverton dans l'Oregon, elle est spécialisée dans la fabrication d'articles de sport.","Nike est une société américaine créée en 1968 par Philip Knight et Bill Bowerman.","fr:Nike","c:d/d3/Nike_Campus%2C_Beaverton_-_DPLA_-_ffa63f1bbaf5cd21aeada3d3978db2b0.jpg"],["Q53472173",121,"mode","Off-White","C","Off-White est une marque italienne de vêtements et d'accessoires de mode appartenant à Off-White LLC. Fondée par l'Américain Virgil Abloh fin 2013 à Milan, elle s'inscrit dans la vague streetwear haut de gamme à l'instar de Vetements ou Balenciaga. La marque est présente internationalement et dispose de 24 magasins à travers le monde, ainsi que de stands de revente à Barneys, Selfridges, Harrods ou les Galeries Lafayette Haussmann.","Off-White est une marque italienne de vêtements et d'accessoires de mode appartenant à Off-White LLC.","fr:Off-White",""],["Q1660552",122,"mode","Patagonia","C","Patagonia est une entreprise californienne spécialisée dans les vêtements techniques destinés aux sports de montagne et de surf, fondée par Yvon Chouinard en 1973. Au fil des années, Patagonia a développé une approche axée sur le développement durable et la protection de l’environnement. Elle met en avant des engagements liés à la lutte contre la crise environnementale, à la responsabilité sociale et à la gouvernance d'entreprise.",119,"fr:Patagonia_(entreprise)","c:9/94/Interior_of_the_Patagonia_outlet_store_in_Geelong_September_2025.jpg"],["Q137023",124,"mode","Primark","R","Primark est une entreprise irlandaise spécialisée dans la distribution de vêtements à bas prix, appartenant à Associated British Foods. Celle-ci est fondée en 1969 en Irlande sous le nom de Penneys puis se développe dans le monde depuis les années 2000. Sa politique commerciale est basée essentiellement sur une réduction des coûts et un volume de vente important, sur le principe de la fast fashion.",109,"fr:Primark","c:1/14/Primark_%2854400449892%29.jpg"],["Q157064",125,"mode","Puma","PC","Puma est une entreprise allemande spécialisée dans la fabrication d'articles de sport fondée en 1948 par Rudolf Dassler, frère aîné d'Adolf Dassler, et basée à Herzogenaurach en Bavière. La famille Pinault, à travers les sociétés Artémis et Kering, était l'actionnaire majoritaire de 2007 jusqu'à son désengagement important entre 2018 et 2021.",111,"fr:Puma_(entreprise)","https://upload.wikimedia.org/wikipedia/fr/thumb/7/72/Puma.svg/330px-Puma.svg.png"],["Q2759606",126,"mode","Quechua","C","Quechua est une marque de produits pour la pratique de la randonnée nature et en montagne. Créée en 1997, cette entreprise est localisée à Passy en Haute-Savoie et compte environ 200 employés. Quechua propose des vêtements techniques, des chaussures, de l'équipement pour le camp et des accessoires pour randonner en toute saison et sur tout type de terrain.","Quechua est une marque de produits pour la pratique de la randonnée nature et en montagne.","fr:Quechua_(marque)","c:9/96/Quechua_climbing_shoes.jpg"],["Q1641437",127,"mode","Ralph Lauren","C","Polo Ralph Lauren est une marque de vêtements américaine haut de gamme fondée par Ralph Lauren en 1967.",null,"fr:Polo_Ralph_Lauren","c:7/78/Gertrude_Rhinelander_Waldo_House_%2851660337406%29.jpg"],["Q653941",128,"mode","Ray-Ban","PC","Ray-Ban est un fabricant de lunettes de soleil et de lunettes de vue d'origine américaine, fondé en 1937 par Bausch & Lomb et appartenant au franco-italien EssilorLuxottica. En 1999, Bausch & Lomb vend la marque au groupe Luxottica.",117,"fr:Ray-Ban","https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Ray-Ban_logo_2.svg/330px-Ray-Ban_logo_2.svg.png"],["Q466183",129,"mode","Reebok","PC","Reebok est un équipementier sportif américain d'origine anglaise fondé en 1895 à Bolton dans le Grand Manchester, et filiale de la société américaine Authentic Brands Group depuis 2021.",116,"fr:Reebok","c:8/85/ReebokSouthEdmontonCommon.jpg"],["Q2120822",130,"mode","Salomon","C","L'entreprise Salomon, fondée en 1947 à Annecy en Haute-Savoie, est une marque spécialisée dans les articles de sports et de loisirs. Elle est distribuée dans plus de 160 pays. Historiquement, elle se développe dans le domaine du ski et plus particulièrement des fixations, mais, à partir des années 2000, connait une diversification vers le trail.",117,"fr:Salomon_(entreprise)","c:a/ab/Trail_running_shoe.jpg"],["Q950042",131,"mode","Stone Island","C","Stone Island est une marque vestimentaire italienne créée en 1982 par Massimo Osti. La marque s'est fait connaître pour son travail et ses expériences sur des matériaux originaux tels que des bâches de camions. Sa maîtrise de la teinture des vêtements déjà confectionnés et une grande technicité dans les procédés de fabrication, ont fait le renom de Stone Island.","Stone Island est une marque vestimentaire italienne créée en 1982 par Massimo Osti.","fr:Stone_Island","https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Stone-Island-Logo.svg/330px-Stone-Island-Logo.svg.png"],["Q1659229",132,"mode","Supreme","C","Supreme est une marque de vêtements streetwear et accessoires de mode fondée à New York en 1994 par James Jebbia au coin de Lafayette Street et de Prince Street. Au commencement, le personnel et les clients du magasin étaient principalement constitués de jeunes skateurs et artistes new-yorkais. Dès le début, les produits sont rapidement épuisés et la vente reste sélective.",115,"fr:Supreme_(vêtements)","https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Supreme_Logo.svg/330px-Supreme_Logo.svg.png"],["Q152784",133,"mode","The North Face","PC","The North Face, Inc. est une société fondée par Douglas Tompkins, militant écologiste, spécialisé dans les vêtements et accessoires de sport.","The North Face, Inc.","fr:The_North_Face","https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/TheNorthFace_logo.svg/330px-TheNorthFace_logo.svg.png"],["Q1539185",134,"mode","Timberland","C","Timberland est une marque de The Timberland Company, une entreprise fabriquant et vendant ses propres produits de textile. Elle est spécialisée dans l'habillement de plein air, notamment les chaussures. Les chaussures de la marque, à l'origine destinées aux bucherons, sont utilisées en principe pour la randonnée pédestre mais restent avant tout un objet d'usage courant. La marque s'est ensuite diversifiée avec des montres, des sacs, et autres objets.",113,"fr:Timberland_(entreprise)","c:e/eb/Image_of_a_pair_of_Tmerberland_boots.png"],["Q634881",135,"mode","Tommy Hilfiger","C","Tommy Hilfiger B.V., est une marque américaine de vêtements de prêt-à-porter, distribuant également des chaussures, des accessoires, des parfums ou des articles d'ameublement. La société est fondée en 1985, et les marchandises de la marque sont vendues dans des grands magasins et plus de 2 000 magasins de détail autonomes dans 100 pays. En 2006, la société de capital-investissement Apax Partners a acquis la société pour environ 1,6 milliard de dollars. En mars 2010, PVH Corp. a racheté la société.",119,"fr:Tommy_Hilfiger_(entreprise)","c:b/bf/Tommy-Hilfiger-Filiale.jpg"],["Q652047",136,"mode","Umbro","C","Umbro est un équipementier sportif anglais fondé en 1924 à Wilmslow. Son siège social se situe à Manchester en Angleterre.","Umbro est un équipementier sportif anglais fondé en 1924 à Wilmslow.","fr:Umbro","https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Umbro_logo_%28current%29.svg/330px-Umbro_logo_%28current%29.svg.png"],["Q2031485",137,"mode","Under Armour","C","Under Armour est une entreprise américaine spécialisée dans le secteur de l'habillement basée à Baltimore. Elle a été fondée en 1996 par Kevin Plank, un ancien footballeur américain de l'université du Maryland.","Under Armour est une entreprise américaine spécialisée dans le secteur de l'habillement basée à Baltimore.","fr:Under_Armour","https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Under_armour_logo.svg/330px-Under_armour_logo.svg.png"],["Q26070",138,"mode","Uniqlo","R","UNIQLO Co., Ltd. est une marque commerciale de l'entreprise Fast Retailing, groupe japonais de conception, confection et distribution de vêtements.","UNIQLO Co., Ltd.","fr:Uniqlo","c:6/6d/Uniqlo_Shinsaibashisuji_Flag_ship_store_Interior_view_2014.jpg"],["Q1135366",139,"mode","Vans","C","Vans est une marque californienne de chaussures de sport, notamment de skateboard, BMX trottinette freestyle et snowboard, filiale du groupe américain VF Corporation.",111,"fr:Vans_(entreprise)","c:d/db/Vans_-_Store_%2851395753693%29.jpg"],["Q147662",140,"mode","Zara","PC","Zara est la principale marque de vêtements de mode pour enfants et pour adultes de la société espagnole Inditex, qui possède aussi les marques Zara Home, Massimo Dutti, Bershka, Pull and Bear, Stradivarius, Uterqüe ou Oysho.",116,"fr:Zara_(vêtements)","c:e/e3/Zara_Store_in_Columbus.jpg"],["Q667425",141,"luxe","Audemars Piguet","C","Audemars Piguet, fondée en 1875 par Jules-Louis Audemars et Edward-Auguste Piguet, est une manufacture d'horlogerie de luxe suisse, installée au Brassus dans la vallée de Joux.",118,"fr:Audemars_Piguet","c:2/26/Place_de_la_Fusterie-04.jpg"],["Q788088",142,"luxe","Baccarat","C","La cristallerie Baccarat est une entreprise verrière et manufacture de cristal de renommée mondiale, située dans la commune de Baccarat, à la limite orientale du département de Meurthe-et-Moselle, en Lorraine. Elle possède, à proximité de ses ateliers, un musée et un café très fréquenté en saison estivale.",115,"fr:Baccarat_(cristallerie)","https://upload.wikimedia.org/wikipedia/fr/thumb/4/4e/LOGO-BACCARAT.jpg/330px-LOGO-BACCARAT.jpg"],["Q1530892",143,"luxe","Balenciaga","PC","Balenciaga est une entreprise française de mode et de luxe d'origine espagnole fondée par l'Espagnol Cristóbal Balenciaga à Saint-Sébastien en 1917, dont le premier nom de son magasin fut Eisa, en hommage à sa mère et à son influence pertinente dans le domaine de la mode. Couturier de la famille royale espagnole, Balenciaga s’installe à Paris à la fin des années 1930 où il s’impose comme le « couturier des couturiers » de la mode parisienne. Il cesse ses activités en 1968 et meurt quelques années plus tard.",110,"fr:Balenciaga","c:c/c0/HK_%E5%B0%96%E6%B2%99%E5%92%80_TST_%E4%BA%BA%E6%96%87%E8%97%9D%E8%A1%93%E8%B3%BC%E7%89%A9%E9%A4%A8_K11_MUSEA_mall_1530pm_May_2020_SS2_47.jpg"],["Q848553",144,"luxe","Boucheron","C","Boucheron est un joaillier français installé place Vendôme à Paris depuis plus d'un siècle. Il appartient aujourd'hui au groupe Kering.","Boucheron est un joaillier français installé place Vendôme à Paris depuis plus d'un siècle.","fr:Boucheron","c:c/c2/Vitrine_Boucheron_150ans.JPG"],["Q752515",145,"luxe","Bulgari","PC","Bulgari est une société italienne fondée en 1884 par l'orfèvre grec ottoman Sotírios Voúlgaris, active dans le domaine du luxe, principalement de la bijouterie, mais également de l'horlogerie, des parfums et des accessoires haut de gamme. Elle appartient depuis 2011 au groupe français LVMH - Moët Hennessy Louis Vuitton.",118,"fr:Bulgari","c:e/ed/Roma%2C_Piazza_Nicosia%2C_20.jpg"],["Q390107",146,"luxe","Burberry","C","Burberry's est à l'origine un tailleur britannique, spécialiste de la confection de manteaux et d'imperméables masculins qui manufacture des vêtements de luxe pour une clientèle riche et exigeante. Avec ses modèles immuables, il s'est imposé comme le représentant de l'élégance masculine sobre, raffinée et de très bonne qualité des classes aisées britanniques. La reine Élisabeth II et le prince Charles lui ont tous deux accordé la Reconnaissance royale en 1955 et en 1989.",110,"fr:Burberry","c:c/c5/Burberry_Chicago.jpg"],["Q538587",147,"luxe","Cartier","C","Cartier est une entreprise du secteur du luxe qui conçoit, fabrique, distribue et vend des bijoux, des montres, des lunettes, des parfums, des sacs et des portefeuilles. Fondée à Paris en 1847 par Louis-François Cartier, l'entreprise est restée sous le contrôle de la famille jusqu'en 1964. La marque est rendue célèbre par son petit-fils Louis Cartier. En 1899, Alfred Cartier décide d’implanter l’entreprise familiale 13 rue de la Paix à Paris, adresse actuelle et cœur historique du savoir-faire de l'entreprise.",115,"fr:Cartier_(entreprise)","c:d/da/Cartier_Paris.jpg"],["Q218115",148,"luxe","Chanel","PC","Chanel ou Chanel SAS est une entreprise française productrice de haute couture, ainsi que de prêt-à-porter, accessoires, parfums et divers produits de luxe. Elle trouve son origine dans la maison de couture qu'avait créée Gabrielle Bonheur Chasnel, dite « Coco Chanel », en 1910, mais résulte du rachat de Chanel par l'entreprise Les Parfums Chanel en 1954.",107,"fr:Chanel","https://upload.wikimedia.org/wikipedia/fr/thumb/3/34/Chanel_logo_complet.png/330px-Chanel_logo_complet.png"],["Q2961620",149,"luxe","Chaumet","C","Chaumet est une maison française de joaillerie, de bijouterie et d’horlogerie fondée en 1780 par Marie-Étienne Nitot.",null,"fr:Chaumet_(entreprise)","https://upload.wikimedia.org/wikipedia/fr/thumb/2/29/Logo-chaumet.png/330px-Logo-chaumet.png"],["Q452136",150,"luxe","Christian Louboutin","PC","Christian Louboutin, né le 7 janvier 1964 à Paris, est un créateur français de chaussures et de sacs à main de luxe.",null,"fr:Christian_Louboutin","c:f/fc/Nmacc-2023-0331-christian-louboutin.jpg"],["Q2975619",151,"luxe","Clarins","C","Clarins est une entreprise familiale française de cosmétiques créée à Paris en 1954 par Jacques Courtin-Clarins. L’entreprise fabrique et commercialise des produits de soin pour la peau, de maquillage et est également un acteur du spa et du bien-être.","Clarins est une entreprise familiale française de cosmétiques créée à Paris en 1954 par Jacques Courtin-Clarins.","fr:Clarins",""],["Q214480",153,"luxe","Dolce & Gabbana","C","Dolce & Gabbana SrL est une entreprise italienne spécialisée dans le luxe fondée par les stylistes italiens Domenico Dolce et Stefano Gabbana à Milan, en Italie. En 2012, leur chiffre d’affaires dépasse le milliard de dollars. La vie privée de Stefano Gabbana et Domenico Dolce est devenue publique en 2005, quand ils ont annoncé leur séparation amoureuse. Les deux stylistes collaborent toujours.",116,"fr:Dolce_&_Gabbana","c:3/3b/Dolce_%26_Gabbana_Bal_Harbour.jpg"],["Q347187",154,"luxe","Dom Pérignon","C","Le Dom Pérignon est une cuvée millésimée issue de vin de Champagne. Elle est élaborée, lors d'années exceptionnelles, par la maison de Champagne Moët & Chandon et fournit 8 millions de bouteilles.","Le Dom Pérignon est une cuvée millésimée issue de vin de Champagne.","fr:Dom_Pérignon_(cuvée)","https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Logo_-_Dom_P%C3%A9rignon.svg/330px-Logo_-_Dom_P%C3%A9rignon.svg.png"],["Q1260606",155,"luxe","Estée Lauder","C","Estée Lauder est une entreprise américaine de production et de distribution de produits de soins pour la peau, de cosmétiques, de parfums et de produits capillaires.",113,"fr:Estée_Lauder_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Est%C3%A9e_Lauder_Companies_Logo.svg/330px-Est%C3%A9e_Lauder_Companies_Logo.svg.png"],["Q926575",156,"luxe","Fendi","C","Fendi est une marque italienne de prêt-à-porter de luxe fondée en 1925 par Adele et Edoardo Fendi, dont la réputation repose sur son choix de chaussures et de fourrures. Depuis 2001, Fendi appartient à la division « Mode & Maroquinerie » du groupe français LVMH. Son siège social se trouve à Rome, dans le Palais de la civilisation italienne.",117,"fr:Fendi","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Fendi_logo.svg/330px-Fendi_logo.svg.png"],["Q599755",157,"luxe","Garnier","C","Garnier est une marque de produits cosmétiques créée en 1904 par Alfred Garnier, et propriété du groupe L'Oréal depuis 1965. Garnier est spécialisé dans les produits de soins capillaires et de soins de la peau.",118,"fr:Garnier_(cosmétique)",""],["Q635484",158,"luxe","Giorgio Armani","C","Giorgio Armani est une entreprise de mode italienne, créée par le styliste Giorgio Armani, à Milan en 1975, avec son ami Sergio Galeotti avec un capital de 10 000 $ US.",116,"fr:Giorgio_Armani_(entreprise)","c:e/eb/GiorgioArmaniViennaKohlmarkt.jpg"],["Q759210",159,"luxe","Givenchy","C","Givenchy, à l'origine une maison de haute couture créée par le grand couturier français Hubert de Givenchy en 1952. Elle devient par la suite une marque de luxe: couture, prêt-à-porter, maroquinerie, bijoux, etc.","Givenchy, à l'origine une maison de haute couture créée par le grand couturier français Hubert de Givenchy en 1952.","fr:Givenchy","c:9/9a/Givenchy_GeorgeV.jpg"],["Q178516",160,"luxe","Gucci","R","Gucci est une maison italienne spécialisée dans la mode et le luxe dont le siège est situé à Florence en Italie. Gucci crée des collections de sacs-à-main, de prêt-à-porter, de chaussures, d'accessoires, de produits cosmétiques, de parfums, et de produits de décoration d'intérieur.","Gucci est une maison italienne spécialisée dans la mode et le luxe dont le siège est situé à Florence en Italie.","fr:Gucci","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Gucci_logo.svg/330px-Gucci_logo.svg.png"],["Q1553251",161,"luxe","Guerlain","C","Guerlain est un parfumeur français. La maison a été créée à Paris en 1828 par Pierre François Pascal Guerlain. Pendant cent cinquante ans, elle est restée propriété de la famille Guerlain. À la suite de son rachat en 1994, Guerlain est désormais une marque de la branche Parfums et Cosmétiques du groupe LVMH.","Guerlain est un parfumeur français.","fr:Guerlain","c:b/b9/Guerlain_Vitrine_de_No%C3%ABl.jpg"],["Q1229287",162,"luxe","Hennessy","C","Jas Hennessy & Co., communément appelé simplement Hennessy, est une entreprise de cognac dont le siège social est situé à Cognac, en France. La Maison a été fondée en 1765 par l'officier militaire irlandais Richard Hennessy et est actuellement le plus grand producteur et exportateur de cognac au monde, avec plus de 100 millions de bouteilles par an.",119,"fr:Hennessy","https://upload.wikimedia.org/wikipedia/fr/thumb/f/fe/Hennessy.svg/330px-Hennessy.svg.png"],["Q931207",164,"luxe","Kering","PC","Kering est un groupe français d'entreprises aujourd'hui numéro deux mondial de l'industrie du luxe après LVMH quant au chiffre d'affaires.",118,"fr:Kering","c:a/a1/H%C3%B4pital_Laennec%2C_Rue_de_S%C3%A8vres%2C_Paris.jpg"],["Q2406369",167,"luxe","Lalique","C","Lalique est une société suisse de luxe, fondée par le maître verrier et créateur de bijoux français René Lalique en 1888. Elle fabrique et distribue des pièces dans différents domaines: objets décoratifs, architecture d’intérieur, bijoux, parfums et pièces d’art.",115,"fr:Lalique","c:3/31/Horse_by_Ren%C3%A9_Jules_Lalique.jpg"],["Q1541268",168,"luxe","Lancôme","C","Lancôme est une marque de cosmétiques et de produits de luxe créée le 21 février 1935 par Armand Petitjean, parfumeur à Paris. Le nom est choisi pour sa sonorité « bien française ». La marque appartient depuis 2019 à la société l'Oréal, coté en bourse.",119,"fr:Lancôme_(cosmétique)",""],["Q504998",170,"luxe","LVMH","E","LVMH - Moët Hennessy Louis Vuitton SE est un groupe français d'entreprises, fondé en 1987 par Alain Chevalier et Henry Racamier, qui est aujourd'hui numéro un mondial de l'industrie du luxe quant au chiffre d'affaires.",118,"fr:LVMH_-_Moët_Hennessy_Louis_Vuitton","c:d/da/La_Samaritaine_depuis_le_pont_Neuf.jpg"],["Q142691",171,"luxe","Montblanc","C","Montblanc International GmbH est une entreprise allemande spécialisée dans la fabrication de stylos de luxe, montres, maroquinerie, bijouterie/joaillerie et parfumerie. En 2009, elle détient 60 % du marché mondial des stylos haut de gamme.",117,"fr:Montblanc_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Montblanc_logo.svg/330px-Montblanc_logo.svg.png"],["Q337408",173,"luxe","Nivea","PC","Nivea est une marque de produits de soin, appartenant au groupe allemand Beiersdorf.",null,"fr:Nivea","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/NIVEA_logo_2021.svg/330px-NIVEA_logo_2021.svg.png"],["Q659224",174,"luxe","Omega","C","Omega est une entreprise suisse d’horlogerie de luxe, fondée en 1848 à la Chaux-de-Fonds, dans le canton de Neuchâtel, en Suisse.",118,"fr:Omega_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Omega_Logo.svg/330px-Omega_Logo.svg.png"],["Q659096",175,"luxe","Patek Philippe","PC","Patek Philippe est une entreprise suisse d'horlogerie de luxe.",null,"fr:Patek_Philippe","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5f/Logo_Patek_Philippe.svg/330px-Logo_Patek_Philippe.svg.png"],["Q193136",176,"luxe","Prada","PC","Prada S.p.A. est une marque fondée en 1913 à Milan par Mario Prada et son frère Martino Prada sous le nom de Fratelli Prada. À l'origine une petite entreprise de maroquinerie et importateur de bagages en provenance d'Angleterre, la marque s'est diversifiée vers le prêt-à-porter à la fin des années 1980, jusqu'à devenir un groupe de luxe grâce à Miuccia Prada entrée en 1970 dans l'entreprise.","Prada S.p.A.","fr:Prada_(entreprise)","c:3/31/Prada_milano.JPG"],["Q62288",177,"luxe","Rolex","PC","Rolex est une manufacture suisse de montres de luxe, fondée en 1905 par Hans Wilsdorf. Son modèle phare Oyster existe depuis 1926. En 2014, elle avait un chiffre d'affaires de 5 milliards de francs suisses et son chiffre a doublé entre 2014 et 2023.","Rolex est une manufacture suisse de montres de luxe, fondée en 1905 par Hans Wilsdorf.","fr:Rolex","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d0/Rolex.svg/330px-Rolex.svg.png"],["Q2408041",178,"luxe","Sephora","PC","Sephora est une chaîne de magasins de vente de parfums et de produits cosmétiques française dont les origines remontent à 1973 et appartenant au groupe LVMH depuis 1997.",119,"fr:Sephora_(entreprise)","c:7/7d/Crowd_%40_Passage_du_Havre_%40_Paris_%2834214305381%29.jpg"],["Q573422",179,"luxe","Swatch","C","Swatch est la marque d’une ligne de montres-bracelet du Swatch Group, positionnée en entrée de gamme.",null,"fr:Swatch","c:9/90/Swatch-Bienne-4.jpg"],["Q645984",180,"luxe","TAG Heuer","C","TAG Heuer est un fabricant suisse de montres de sport, de luxe et de chronographes de précision.",null,"fr:TAG_Heuer","c:5/5e/Tagheuer-indy500.jpg"],["Q1066858",181,"luxe","Tiffany & Co.","C","Tiffany & Co. est une entreprise américaine de joaillerie et d'art de la table, fondée par Charles Lewis Tiffany et John B. Young le 18 septembre 1837 à New York.","Tiffany & Co.","fr:Tiffany_&_Co.","c:f/f2/Tiffany_blue_box_2.jpg"],["Q649646",182,"luxe","Valentino","C","Valentino est une maison de couture italienne, créée à Rome en 1960 par Giancarlo Giammetti et Valentino Garavani. Filiale du Valentino Fashion Group, elle est la propriété de la famille princière du Qatar depuis 2012, et cède 30% de son capital à Kering en 2023. Jacopo Venturini est CEO de Valentino depuis 2020 et Alessandro Michele directeur artistique depuis 2024.","Valentino est une maison de couture italienne, créée à Rome en 1960 par Giancarlo Giammetti et Valentino Garavani.","fr:Valentino_(entreprise)","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Valentino_logo.svg/330px-Valentino_logo.svg.png"],["Q2708181",183,"luxe","Van Cleef & Arpels","C","Van Cleef & Arpels est une entreprise française de haute joaillerie, joaillerie, horlogerie et parfums de luxe fondée en 1906 par Alfred Van Cleef et son beau-frère Salomon dit Charles Arpels à Paris. Leurs pièces sont souvent ornées de fleurs, d'animaux ou de fées et ont été portées par des femmes comme l'impératrice Farah, la duchesse de Windsor, Grace Kelly, Elizabeth Taylor ou Eva Perón.",117,"fr:Van_Cleef_&_Arpels","c:e/e6/Paris_H%C3%B4tel_de_S%C3%A9gur_22_place_Vend%C3%B4me_2012_3.jpg"],["Q696376",184,"luxe","Versace","C","Versace est le nom d'usage de l'entreprise italienne de mode de luxe Gianni Versace S.r.l., fondée à Milan en 1978 par la fratrie Versace: Gianni Versace, Santo Versace et Donatella Versace.",118,"fr:Versace","c:a/af/Berlin_-_Kurf%C3%BCrstendamm_193-194.jpg"],["Q1477321",185,"luxe","Yves Rocher","C","Yves Rocher France est une entreprise française de cosmétiques fondée par Yves Rocher à La Gacilly en 1959 et dont le siège social est situé à Rennes. Active dans le secteur de la cosmétique végétale, elle est la propriété du groupe familial Groupe Rocher et compte 2 500 boutiques dont plus de 600 en France. Première marque de cosmétique en France en valeur, elle développe une approche fondée sur la dermo-botanique et la cosmétique naturelle.",117,"fr:Yves_Rocher_(entreprise)","c:3/3f/HK_SKD_%E5%B0%87%E8%BB%8D%E6%BE%B3_TKO_%E6%97%A5%E5%87%BA%E5%BA%B7%E5%9F%8E_Lohas_Park_shopping_mall_shop_Yves_Rocher_December_2021_Px3_01.jpg"],["Q2282172",186,"luxe","Yves Saint Laurent","C","Yves Saint Laurent, communément abrégée YSL, est une entreprise française de luxe spécialisée dans le prêt-à-porter, la maroquinerie, les chaussures, et les accessoires de luxe.",119,"fr:Yves_Saint_Laurent_(entreprise)","c:3/3d/HK_CWB_Time_Square_mall_shop_YSL_clothing_logo_July-2014_RedMi.jpg"],["Q128738",187,"alimentation","AB InBev","PC","Anheuser-Busch InBev est un groupe brassicole belge et le plus grand groupe brassicole au monde de par le volume de bière brassée. Coté en bourse, son siège social est situé à Louvain en Belgique. Le groupe résulte de l'acquisition de Anheuser-Busch par InBev en 2008.",115,"fr:Anheuser-Busch_InBev",""],["Q2881890",188,"alimentation","Banania","C","Banania est une marque française de boisson et de produits chocolatés. La marque a été lancée en 1914 par Pierre-François Lardet et appartient à la société Nutrimaine du groupe agroalimentaire Nutrial également propriétaire de Benco. La production de Banania a été délocalisée en Allemagne en 2019.","Banania est une marque française de boisson et de produits chocolatés.","fr:Banania","c:a/a5/Banania_bo%C3%AEte_m%C3%A9tallique.jpg"],["Q64506735",189,"alimentation","Barilla","C","Barilla est une entreprise italienne fondée en 1877 à Parme, premier producteur de pâtes au monde.","","en:Barilla","c:9/93/Salsola_soda_Rignanese.jpg"],["Q816412",190,"alimentation","Ben & Jerry's","PC","Ben & Jerry’s est une marque américaine, fondée en 1978 par Ben Cohen et Jerry Greenfield, qui commercialise des crèmes glacées. L’entreprise a son siège social à South Burlington dans l’État du Vermont aux États-Unis et appartient au groupe Unilever depuis 2000.",119,"fr:Ben_&_Jerry's","c:e/ec/1.20.10HobokenBen%26Jerry%27sByLuigiNovi2.jpg"],["Q2904651",191,"alimentation","BN","C","La Biscuiterie nantaise est une biscuiterie industrielle française, emblématique de la ville de Nantes, qui fabrique des biscuits, notamment la marque commerciale « choco BN », filiale du groupe britannico-turc Pladis.",116,"fr:Biscuiterie_nantaise","https://upload.wikimedia.org/wikipedia/fr/thumb/e/ed/Logo-bn.png/330px-Logo-bn.png"],["Q892279",192,"alimentation","Bonduelle","C","Bonduelle est une entreprise multinationale d'origine française spécialisée dans la transformation industrielle des légumes: conserves, surgelés et produits frais prêts à l'emploi. Ses produits, sous ses propres marques ou sous marques de distributeur, sont vendus principalement par les canaux de distribution classiques. Elle est cotée à la Bourse de Paris.",115,"fr:Bonduelle","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Bonduelle_WW_Corporate_Brand-Legal-v.svg/330px-Bonduelle_WW_Corporate_Brand-Legal-v.svg.png"],["Q54552919",193,"alimentation","Bonne Maman","C","Bonne Maman est une marque française de confitures et de biscuits, reconnaissable à ses pots au couvercle à carreaux rouges et blancs.","","en:Bonne_Maman","c:1/1f/Bonne_maman_confiture.JPG"],["Q2940481",195,"alimentation","Carte d'Or","C","Carte d'Or est une marque de glaces industrielles internationale créée en France en 1978. Elle appartient au groupe Unilever et est une gamme de marque de Motta jusqu'en 1994, puis de Miko lorsqu'Unilever intègre cette marque française dans son portefeuille après son rachat. La fabrication est alors transférée de l'usine d'Argentan à la nouvelle usine Miko de Saint-Dizier - Trois Fontaines dont elle devient la principale activité.","Carte d'Or est une marque de glaces industrielles internationale créée en France en 1978.","fr:Carte_d'Or","https://upload.wikimedia.org/wikipedia/fr/thumb/5/58/CDO_logo.jpeg/330px-CDO_logo.jpeg"],["Q860761",196,"alimentation","Chimay","C","La brasserie de Chimay est une brasserie trappiste de l'abbaye de Scourmont, en Belgique, connue pour ses bières bleue, rouge et blanche.","","en:Chimay_Brewery","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/Chimay.png/330px-Chimay.png"],["Q938535",197,"alimentation","Chupa Chups","C","Chupa Chups est une marque de sucettes créée en 1958 par l'Espagnol Enric Bernat, actuellement détenue par la société multinationale italo-néerlandaise Perfetti Van Melle. Elle est présente dans plus de 160 pays à travers le monde. Le nom vient du verbe espagnol chupar, qui signifie « sucer ».",117,"fr:Chupa_Chups","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d9/Chupa-chups.svg/330px-Chupa-chups.svg.png",{"cats":["marques","enfance"]}],["Q2813",198,"alimentation","Coca-Cola","E","Coca-Cola, parfois abrégé Coca ou Cola dans les pays francophones ou Coke en Amérique du Nord et dans certains pays européens et africains, est une marque américaine de soda de type cola fabriquée par The Coca-Cola Company. Cette marque a été déposée en 1886. Ce nom provient de deux ingrédients utilisés pour sa composition originelle: la feuille de coca et la noix de kola.",115,"fr:Coca-Cola","c:8/86/CocaCola-001.jpg"],["Q864987",199,"alimentation","Corona","PC","Corona est une marque de bière lager mexicaine produite dans plusieurs brasseries du Mexique par Grupo Modelo.",null,"fr:Corona_(bière)","https://upload.wikimedia.org/wikipedia/fr/thumb/7/71/Corona_Extra.svg/330px-Corona_Extra.svg.png"],["Q329426",201,"alimentation","Danone","PC","Danone est une multinationale alimentaire française dont le siège social est à Paris. L’entreprise est cotée sur Euronext à la Bourse de Paris, où elle est incluse dans l’indice boursier CAC 40. En 2020, elle devient la première société cotée à adopter le statut de société à mission, introduit par la loi Pacte de 2019.","Danone est une multinationale alimentaire française dont le siège social est à Paris.","fr:Danone","https://upload.wikimedia.org/wikipedia/fr/thumb/c/ca/Danone_Logo_corporate.png/330px-Danone_Logo_corporate.png"],["Q2646636",202,"alimentation","Desperados","C","Desperados est une marque de bière aromatisée d'origine alsacienne appartenant aujourd'hui au groupe Heineken et produite en Belgique par la brasserie Alken-Maes.",112,"fr:Desperados_(bière)","c:f/f1/Desperados-Flasche.jpg"],["Q776795",203,"alimentation","Doritos","PC","Doritos est une marque de chips tortillas assaisonnées créée par Arch West et produites depuis 1964 par l'entreprise alimentaire américaine Frito-Lay, filiale du groupe PepsiCo. Les Doritos sont des triangles de maïs frits et aromatisés, une recette qui s'inspire des totopo mexicains. De plus, le nom « Doritos » provient de l’espagnol mexicain « doradito », qui signifie « petit doré », en référence à la couleur des chips.",116,"fr:Doritos","c:9/9b/Logo_Doritos.png"],["Q387897",204,"alimentation","Duvel","C","Duvel Moortgat est un groupe brassicole dont le siège se trouve à Puurs dans la province d'Anvers.",null,"fr:Duvel_Moortgat","c:1/11/Duveltripelhop2012.jpg"],["Q9935",205,"alimentation","Fanta","PC","Fanta est une marque commerciale de soda allemande produite et distribuée par The Coca-Cola Company.",null,"fr:Fanta","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fanta_2023.svg/330px-Fanta_2023.svg.png"],["Q269792",206,"alimentation","Ferrero","PC","Ferrero est une entreprise agroalimentaire italienne, créée en 1946 par Pietro Ferrero à Alba en Italie, spécialisée dans la confiserie industrielle et connue pour des produits phares tels que Nutella, Kinder, Ferrero Rocher, Mon Chéri, Delacre et Tic Tac.",116,"fr:Ferrero","c:c/c3/Ferrero_-_panoramio_%282%29.jpg"],["Q526516",207,"alimentation","Ferrero Rocher","PC","Le Ferrero Rocher est une confiserie sphérique produite par le groupe italien Ferrero depuis 1982. Jusqu'au milieu des années 1990, la friandise s'appelait Ferrero Roche d'Or.","Le Ferrero Rocher est une confiserie sphérique produite par le groupe italien Ferrero depuis 1982.","fr:Ferrero_Rocher","c:2/20/2023_Ferrero_Rocher_%283%29.jpg"],["Q3073639",208,"alimentation","Fleury Michon","C","Fleury Michon est une entreprise agroalimentaire française, cotée à la bourse de Paris. Cette entreprise fabrique de la charcuterie et en particulier du jambon de porc, du jambon de volaille et et du jambon végétarien, mais également des plats cuisinés individuels et du surimi. L'entreprise fabrique également des produits à destination de la restauration hors domicile et des établissements de santé. Elle détient des filiales spécialisées dans le Catering aérien international.","Fleury Michon est une entreprise agroalimentaire française, cotée à la bourse de Paris.","fr:Fleury_Michon",""],["Q55402212",209,"alimentation","Galler","C","Galler est une marque belge de chocolat fondée en 1976 par Jean Galler, fournisseur de la Cour de Belgique.","","en:Galler",""],["Q194297",211,"alimentation","Guinness","R","Guinness est une marque de bière ainsi qu'une brasserie irlandaise. Fondée en 1759, celle-ci est devenue une entreprise de taille mondiale avec l'acquisition en 1986 de Distillers Company, un groupe écossais possédant notamment les marques de whiskies Johnnie Walker, Ballantine's ou Chivas Regal.","Guinness est une marque de bière ainsi qu'une brasserie irlandaise.","fr:Guinness","c:7/7e/Guinness_brewery%2C_front_view.jpg"],["Q169552",212,"alimentation","Haribo","R","Haribo est une marque de confiserie allemande et le nom d'une multinationale fondée en 1920 par le confiseur allemand Hans Riegel. Elle tient son nom de son inventeur et de sa ville d'origine, Bonn: Hans Riegel Bonn.",117,"fr:Haribo","c:2/2e/2013-09-02_Haribo-Zentrale%2C_Hans-Riegel-Stra%C3%9Fe_1%2C_Bonn-Kessenich_IMG_0929.jpg",{"cats":["marques","enfance"]}],["Q854383",213,"alimentation","Heineken","C","Heineken est une bière blonde néerlandaise créée en 1873, l'une des plus vendues au monde, reconnaissable à sa bouteille verte et son étoile rouge.","","en:Heineken","c:a/a8/Two_glasses_of_Heineken_Pilsener.jpg"],["Q850324",214,"alimentation","Heinz","PC","H. J. Heinz Company, généralement nommée Heinz est une entreprise agroalimentaire américaine qui fabrique et distribue des sauces, des plats préparés et de la nutrition infantile dans plus de 200 pays.","H.","fr:Heinz_(entreprise)","c:6/65/2008-05-24_Pittsburgh_014_Penn_St%2C_13th_St%2C_Heinz_Building_%282669437590%29.jpg"],["Q1143333",215,"alimentation","Häagen-Dazs","PC","Häagen-Dazs est une marque commerciale de crème glacée industrielle, principalement en pot ainsi qu'en cornet, créée par Reuben et Rose Mattus. Le nom de la marque a été inventé en 1961 aux États-Unis. C'est aussi devenu l'enseigne d'une chaîne de magasins d'environ 900 points de vente essentiellement franchisés où sont commercialisées les glaces de sa propre marque dans le monde entier.",116,"fr:Häagen-Dazs","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/H%C3%A4agen-Dazs_Logo.svg/330px-H%C3%A4agen-Dazs_Logo.svg.png"],["Q130326112",217,"alimentation","Kellogg's","PC","Kellogg's est une entreprise américaine de céréales pour petit-déjeuner, célèbre pour ses Corn Flakes et le tigre Tony des Frosties.","","en:Kellogg's","c:3/36/Kellogg_World_Headquarters_%28battlecreekcvb%29_001.jpg"],["Q15410057",218,"alimentation","Kinder","C","Kinder est une marque de confiseries chocolatées de l'entreprise agroalimentaire italienne Ferrero.",null,"fr:Kinder","c:4/4f/Kinder_products_at_the_supermarket.JPG"],["Q181042",219,"alimentation","Kinder Surprise","C","Kinder Surprise est une marque commerciale apposée sur un œuf en chocolat fabriqué par le groupe d'industrie agroalimentaire Ferrero. Cette marque est une déclinaison de la marque « Kinder ».",108,"fr:Kinder_Surprise","c:e/e4/Kinder_Surprise_Logo_%28English%29.png",{"cats":["marques","enfance"]}],["Q367251",220,"alimentation","Kit Kat","C","Kit Kat est une marque commerciale de biscuits enrobés de chocolat créée en Angleterre en 1935 par Rowntree. Elle est actuellement fabriquée dans le monde entier par Nestlé qui a racheté Rowntree en 1988, sauf aux États-Unis, où la fabrication Kit Kat est assurée par Hershey's.","Kit Kat est une marque commerciale de biscuits enrobés de chocolat créée en Angleterre en 1935 par Rowntree.","fr:Kit_Kat","https://upload.wikimedia.org/wikipedia/fr/thumb/c/c9/KitKat_logo.svg/330px-KitKat_logo.svg.png"],["Q415455",221,"alimentation","Knorr","C","Knorr est une marque allemande de soupes, bouillons et sauces fondée en 1838, aujourd'hui propriété d'Unilever.","","fr:Knorr_(homonymie)",""],["Q1397604",222,"alimentation","Kronenbourg","C","Brasseries Kronenbourg est une entreprise brassicole française, filiale depuis 2008 du groupe danois Carlsberg. Son siège se situe à Obernai en Alsace.","Brasseries Kronenbourg est une entreprise brassicole française, filiale depuis 2008 du groupe danois Carlsberg.","fr:Brasseries_Kronenbourg","c:5/5c/Logo_Brasseries_Kronenbourg_2023.png"],["Q1799825",223,"alimentation","Lactalis","C","Lactalis est une multinationale française de l'industrie agroalimentaire, présente principalement dans le secteur des produits laitiers.",117,"fr:Lactalis","https://upload.wikimedia.org/wikipedia/fr/thumb/4/4f/Lactalis2023Logo.svg/330px-Lactalis2023Logo.svg.png"],["Q723513",224,"alimentation","Lay's","C","Lay's est le nom d'une marque commerciale de chips de pomme de terre et à l'origine celui de la société américaine qui créa cette marque en 1932.",118,"fr:Lay's","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Lay%27s_2025.svg/330px-Lay%27s_2025.svg.png"],["Q152822",227,"alimentation","Lindt & Sprüngli","PC","Lindt & Sprüngli AG est un fabricant de chocolat ayant son siège social à Kilchberg dans le canton de Zurich en Suisse.",null,"fr:Lindt_&_Sprüngli","c:8/84/Z%C3%BCrichsee_-_Kilchberg_Lindt_%26_Spr%C3%BCngli_IMG_0227.JPG"],["Q874407",228,"alimentation","Lipton","C","Lipton est une marque alimentaire britannique spécialisée dans les soupes, le thé et les boissons à base de thé. Créée dans les années 1870 par Thomas Lipton, elle a été la propriété d'Unilever puis a été rachetée par le fonds CVC Capital Partners. Elle fait désormais partie du groupe Lipton Teas and Infusions, qui réunit trois marques commercialisant des thés et infusions: Lipton, Éléphant et Pukka. La marque Lipton se vend dans plus de 150 pays.","Lipton est une marque alimentaire britannique spécialisée dans les soupes, le thé et les boissons à base de thé.","fr:Lipton","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Lipton_logo_%282014-2026%29.svg/330px-Lipton_logo_%282014-2026%29.svg.png"],["Q739550",230,"alimentation","M&M's","PC","M&M's est une marque de confiserie, d'origine américaine, appartenant à Mars Incorporated, utilisée pour des dragées au chocolat et aux cacahuètes. D'autres variantes existent: amandes, beurre de cacahuètes, etc.",119,"fr:M&M's","c:e/e5/Plain-M%26Ms-Pile.jpg"],["Q688424",231,"alimentation","Maggi","PC","Maggi est une entreprise suisse d'aide culinaire fondée par Julius Maggi en 1885 et qui fait partie du groupe Nestlé depuis 1947.",116,"fr:Maggi","https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Maggi_logo.svg/330px-Maggi_logo.svg.png"],["Q660801",232,"alimentation","Magnum","C","Magnum est une marque commerciale de crèmes glacées. Depuis sa scission du groupe néerlando-britannique Unilever en juillet 2025, elle fait partie d'une entité autonome: The Magnum Ice Cream Company.","Magnum est une marque commerciale de crèmes glacées.","fr:Magnum_(marque)","c:5/5a/Magnum_ice_cream.jpg"],["Q31305",233,"alimentation","Mars","C","Mars est une barre chocolatée produite par l'entreprise Mars. C'est une version plus douce de la barre Milky Way que Mars Incorporated produit aux États-Unis.","Mars est une barre chocolatée produite par l'entreprise Mars.","fr:Mars_(barre_chocolatée)","c:5/52/2023_Baton_Mars_%282%29.jpg"],["Q1046535",234,"alimentation","Mentos","C","Mentos est une marque de confiserie du groupe italien Perfetti Van Melle. Leur produit se présente sous la forme d'une pastille dragéifiée disponible en différents parfums, vendue en tubes.","Mentos est une marque de confiserie du groupe italien Perfetti Van Melle.","fr:Mentos","c:8/80/Mentos.jpg"],["Q3308815",235,"alimentation","Michel et Augustin","C","Michel et Augustin est une marque française de produits alimentaires créée en 2004 par Augustin Paluel-Marmont et Michel de Rovira, propriété du groupe Ferrero depuis décembre 2023 via un holding belge CTH Invest.",113,"fr:Michel_et_Augustin","https://upload.wikimedia.org/wikipedia/en/thumb/5/59/Vache_%C3%A0_boire.jpg/330px-Vache_%C3%A0_boire.jpg"],["Q757388",236,"alimentation","Milka","PC","Milka est une marque commerciale de produits au chocolat créée en Suisse par Suchard en 1901 et détenue actuellement par le groupe américain Mondelez International, issu d'une scission de l'Américain Kraft Foods qui avait acquis la marque en 1990. Basée en Allemagne à Lörrach, la marque, produite actuellement dans une dizaine de pays européens, mais pas en Suisse, utilise largement l'image des Alpes pour son marketing.",116,"fr:Milka","https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Milka_purple_logo18.svg/330px-Milka_purple_logo18.svg.png"],["Q544293",237,"alimentation","Monster Energy","R","Monster Energy, souvent abrégée en Monster est une boisson énergisante lancée par Hansen Natural en 2002. Le logo représente une griffure triple. La gamme comporte des boissons énergisantes aux divers arômes fruités et des boissons gazeuses à base de thé, de jus de fruits et de taurine.","Monster Energy, souvent abrégée en Monster est une boisson énergisante lancée par Hansen Natural en 2002.","fr:Monster_Energy","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d4/Logo_Monster_Energy.webp/330px-Logo_Monster_Energy.webp"],["Q503191",238,"alimentation","Nescafé","C","Nescafé est une marque de café instantané commercialisée par l'entreprise suisse Nestlé.",null,"fr:Nescafé","c:2/2f/Nescaf%C3%A8_instant_coffee%2C_2019-%2801%29.jpg"],["Q301301",239,"alimentation","Nespresso","C","Nespresso, ou Nestlé Nespresso S.A., est une marque commerciale de la Société des Produits Nestlé. Positionnée sur le marché du café en dosette, elle propose des machines à café utilisant des capsules en aluminium.","Nespresso, ou Nestlé Nespresso S.A., est une marque commerciale de la Société des Produits Nestlé.","fr:Nespresso","c:1/1f/Nespressotab.jpg"],["Q1150326",240,"alimentation","Nesquik","C","Nesquik est une marque de poudre chocolatée américaine produite par Nestlé. Commercialisée initialement sous le nom Nestle Quik aux États-Unis dès 1948, cette préparation pour boisson est lancée en Europe au cours des années 1950. Depuis 1961 la plus grosse usine de production de Nesquik se trouve à Pontarlier en France.","Nesquik est une marque de poudre chocolatée américaine produite par Nestlé.","fr:Nesquik","c:c/c6/Nesquik_granulado_lata.jpg"],["Q160746",241,"alimentation","Nestlé","R","Nestlé SA est une multinationale suisse fondée en 1873 par Henri Nestlé. Elle est un des plus importants acteurs de l'industrie agroalimentaire de la planète. Son siège social est situé à Vevey.","Nestlé SA est une multinationale suisse fondée en 1873 par Henri Nestlé.","fr:Nestlé","https://upload.wikimedia.org/wikipedia/fr/thumb/8/8a/Logo_Nestle.svg/330px-Logo_Nestle.svg.png"],["Q97322777",244,"alimentation","Oasis","C","Oasis est une marque de boisson française créée en 1966 par la Société d'eaux Volvic, et appartenant à la filiale française du groupe japonais Suntory depuis 2006. Elle est la première marque de boissons aux fruits non gazeuse en France, Italie et Belgique et la troisième en Suisse. Elle se positionne comme la troisième marque sur le marché des soft drinks derrière Coca-Cola. La marque Oasis est également utilisée pour les glaces par la société Froneri.",113,"fr:Oasis_(marque_de_boisson)","https://upload.wikimedia.org/wikipedia/fr/thumb/6/6c/Logo-oasis.png/330px-Logo-oasis.png",{"cats":["marques","enfance"]}],["Q138585",246,"alimentation","Oreo","PC","Oreo est la marque déposée d'un biscuit en sandwich américain, produit par la marque américaine Nabisco. La forme courante se compose d'une garniture sucrée blanche, placée entre deux biscuits ronds au chocolat.","Oreo est la marque déposée d'un biscuit en sandwich américain, produit par la marque américaine Nabisco.","fr:Oreo","c:3/3e/Oreo-Two-Cookies.jpg"],["Q43146509",247,"alimentation","Orval","C","La brasserie d'Orval est une brasserie trappiste de l'abbaye d'Orval, en Gaume (Belgique), qui produit une bière unique reconnaissable à sa bouteille en forme de quille.","","en:Orval_Brewery","https://upload.wikimedia.org/wikipedia/en/thumb/d/d5/Orval_logo.png/330px-Orval_logo.png"],["Q3362543",248,"alimentation","Panzani","C","Panzani est un fabricant de pâtes alimentaires d'origine française. La société a été créée en 1946 à Parthenay par Jean Panzani et appartient depuis fin 2021 au fonds d'investissement CVC Capital Partners.","Panzani est un fabricant de pâtes alimentaires d'origine française.","fr:Panzani","https://upload.wikimedia.org/wikipedia/fr/thumb/a/ac/Vect_Panzani_LogoPantone_Transversal.png/330px-Vect_Panzani_LogoPantone_Transversal.png"],["Q47719",249,"alimentation","Pepsi","R","Pepsi, anciennement Pepsi-Cola, est une marque de cola, créée par Caleb Bradham en 1893 à New Bern aux États-Unis. Elle est commercialisée par la société PepsiCo.","Pepsi, anciennement Pepsi-Cola, est une marque de cola, créée par Caleb Bradham en 1893 à New Bern aux États-Unis.","fr:Pepsi","https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Pepsi_2023.svg/330px-Pepsi_2023.svg.png"],["Q3403299",251,"alimentation","Prince","C","Prince est une marque de biscuits de LU, filiale du groupe Mondelēz International, créé en 1870 par le belge Edward De Beukelaer. Le prince est caractérisé par son biscuit rond dentelé fourré aux saveurs chocolat et son personnage emblématique.",118,"fr:Prince_(biscuit)","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f2/Logo_Prince_de_LU.PNG/330px-Logo_Prince_de_LU.PNG",{"cats":["marques","friterie"]}],["Q528187",252,"alimentation","Pringles","PC","Pringles est une marque commerciale de chips reconstituées. Lancée à l'origine par Procter & Gamble, elle appartient depuis 2012 au groupe Kellogg's.","Pringles est une marque commerciale de chips reconstituées.","fr:Pringles","c:8/89/Pringles_chips.JPG",{"cats":["marques","enfance"]}],["Q3184038",253,"alimentation","Président","C","Président est une marque commerciale pour une série de fromages industriels et de beurre français du groupe agroalimentaire Lactalis, créée par Michel Besnier en 1968.",107,"fr:Président_(marque)","https://upload.wikimedia.org/wikipedia/fr/thumb/b/ba/Logo_Pr%C3%A9sident_%28fromage%29.svg/330px-Logo_Pr%C3%A9sident_%28fromage%29.svg.png"],["Q51482",254,"alimentation","Red Bull","R","Red Bull est une marque de boissons énergisantes autrichienne commercialisée par l’entreprise du même nom depuis 1984.",null,"fr:Red_Bull","c:d/d9/Red_bull_1_%2851281069494%29.jpg"],["Q21502146",255,"alimentation","Ricard","C","Ricard est une marque française de pastis créée en 1932 par Paul Ricard à Marseille, l'apéritif anisé emblématique du sud de la France.","","en:Ricard",""],["Q838651",256,"alimentation","Schweppes","C","Schweppes est une marque de boisson vendue dans le monde entier, fondée par Johann Jakob Schweppe. Son offre se compose de nombreuses boissons gazeuses aromatisées.","Schweppes est une marque de boisson vendue dans le monde entier, fondée par Johann Jakob Schweppe.","fr:Schweppes","https://upload.wikimedia.org/wikipedia/fr/thumb/5/52/Schweppes.png/330px-Schweppes.png"],["Q714179",257,"alimentation","Snickers","PC","Snickers est une marque commerciale de barre chocolatée issue de l'industrie agroalimentaire. La marque est la propriété du groupe nord-américain Mars Incorporated; cette confiserie est fabriquée dans ses usines. Cette confiserie fait de l'assemblage d'un morceau de nougat couvert de cacahuètes grillées et de caramel, le tout enrobé de chocolat au lait.","Snickers est une marque commerciale de barre chocolatée issue de l'industrie agroalimentaire.","fr:Snickers","c:5/57/Snickers-broken.JPG"],["Q2786794",258,"alimentation","Spa","C","L'eau de SPA est une eau minérale belge plate ou pétillante exploitée depuis plusieurs sources à Spa en province de Liège. Elle est produite par Spa Monopole S.A. qui fait partie du groupe Spadel comme l'eau minérale de Bru, les Grandes Sources de Wattwiller.",115,"fr:Spa_(eau_minérale)","https://upload.wikimedia.org/wikipedia/fr/thumb/e/eb/Spa-logo-black.png/330px-Spa-logo-black.png"],["Q206978",259,"alimentation","Sprite","C","Sprite est une boisson gazeuse à base d'extraits de citron et de lime créée par The Coca-Cola Company en 1961. Son goût est proche de la limonade. Le Sprite contient de l'eau gazéifiée, du sucre, des acidifiants: acide citrique, citrate de sodium, des arômes naturels de citron-citron vert et un édulcorant: les glycosides de stéviol. Il s'agit du produit concurrent au 7 Up de l'autre géant américain du soda, PepsiCo. Apparue en France depuis 1984.","Sprite est une boisson gazeuse à base d'extraits de citron et de lime créée par The Coca-Cola Company en 1961.","fr:Sprite_(soda)","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Sprite_2022.svg/330px-Sprite_2022.svg.png"],["Q1050530",261,"alimentation","Tic Tac","C","Tic Tac est une marque de petites dragées colorées fabriquées par le groupe de confiseur italien Ferrero. La ligne est centrée autour des saveurs orange et menthe, bien que d'autres parfums existent. Produits depuis 1969, les Tic Tac sont vendus dans de petites boîtes rectangulaires transparentes munies d'un couvercle avec une charnière.","Tic Tac est une marque de petites dragées colorées fabriquées par le groupe de confiseur italien Ferrero.","fr:Tic_Tac_(marque)","https://upload.wikimedia.org/wikipedia/fr/thumb/1/13/Logo_Tic_Tac.png/330px-Logo_Tic_Tac.png"],["Q215707",262,"alimentation","Toblerone","PC","Toblerone est une marque de chocolat d'origine suisse créée par Theodor Tobler en 1908 et actuellement détenue par le groupe américain Mondelez International, issu d'une scission de l'américain Kraft Foods qui avait acquis la marque en 1990.",117,"fr:Toblerone","c:c/cc/Toblerone_3362.jpg"],["Q1846049",263,"alimentation","Tropicana","C","Tropicana Brands Group, ou simplement Tropicana, est une multinationale agroalimentaire américaine fondée en 1947 par Anthony T. Rossi spécialisée dans le domaine des jus de fruits. C'est également la marque commerciale sous laquelle sont vendus ses produits. Le siège de l'entreprise se trouve à Chicago.",117,"fr:Tropicana","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b9/Tropicana_Logo_2024.png/330px-Tropicana_Logo_2024.png"],["Q869733",264,"alimentation","Twix","C","Twix est une barre chocolatée fabriquée par Mars. Elle est constituée d'un biscuit en son centre, recouvert de caramel et enrobé de chocolat au lait, largement inspiré de la célèbre confiserie écossaise shortbread millionnaire. Les Twix ayant une section plus petite que les autres barres chocolatées, ils sont emballés par paires. Le Twix fut introduit pour la première fois au Royaume-Uni en 1967, puis aux États-Unis en 1979.","Twix est une barre chocolatée fabriquée par Mars.","fr:Twix","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f1/Logo_de_Twix_%282025%29.svg/330px-Logo_de_Twix_%282025%29.svg.png"],["Q2308887",265,"alimentation","Vittel","C","Vittel est une marque d'eau minérale en bouteille française moyennement minéralisée appartenant à Nestlé Waters, la division eaux de la multinationale agroalimentaire Nestlé depuis 1992. Elle tire son nom de la ville homonyme où se situe la source.",115,"fr:Vittel_(eau_minérale)","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a1/Logo_Vittel.svg/330px-Logo_Vittel.svg.png"],["Q1047243",266,"alimentation","Volvic","C","Volvic est une marque d'eau en bouteille commercialisée depuis 1935. Exploitée par la Société des eaux de Volvic, elle appartient au groupe agroalimentaire Danone depuis 1992.","Volvic est une marque d'eau en bouteille commercialisée depuis 1935.","fr:Volvic_(eau_en_bouteille)","c:b/ba/Volvic_Logo.png"],["Q2925606",269,"restauration","Brioche dorée","C","La Brioche dorée est une entreprise française de restauration rapide fondée en 1976 par Louis Le Duff, pionnière de la restauration rapide à la française.",118,"fr:Brioche_dorée","https://upload.wikimedia.org/wikipedia/fr/thumb/c/c4/Logo_Brioche_dor%C3%A9e.svg/330px-Logo_Brioche_dor%C3%A9e.svg.png"],["Q944655",270,"restauration","Buffalo Grill","C","Buffalo Grill est une enseigne de restauration française spécialisée dans les grillades de viande et ayant pour thème le voyage en Amérique.",117,"fr:Buffalo_Grill",""],["Q177054",271,"restauration","Burger King","R","Burger King, parfois abrégé en son sigle BK, appelé Hungry Jack's en Australie, est une chaîne de restauration rapide qui compte plus de 18 800 lieux de ventes dans 100 pays, dont les deux tiers aux États-Unis et beaucoup au Canada. Ses principaux concurrents sont McDonald's et KFC. Le siège social de Burger King est situé à 5505 Blue Lagoon Drive, Miami-Dade County, en Floride, près de Miami, le lieu d'origine du restaurant.",117,"fr:Burger_King","https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Burger_King_2020.svg/330px-Burger_King_2020.svg.png"],["Q491516",272,"restauration","Chick-fil-A","R","Chick-fil-A est une chaîne de restauration rapide américaine spécialisée dans les plats à base de poulet. La société a son siège à Atlanta, dans l'État de Géorgie, et est la deuxième plus grande marque de fast-food spécialisée dans le poulet aux États-Unis. Chick-fil-A est souvent associée aux États américains du sud mais la chaîne s'est également étendue dans le sud-ouest et dans le Midwest.","Chick-fil-A est une chaîne de restauration rapide américaine spécialisée dans les plats à base de poulet.","fr:Chick-fil-A","c:2/2d/Chick_Fil_A_-_Cranberry_TWP%2C_PA_-_panoramio.jpg"],["Q839466",273,"restauration","Domino's Pizza","PC","Domino's Pizza est une multinationale américaine de la restauration rapide spécialisée dans la préparation et la livraison de pizza.",112,"fr:Domino's_Pizza","c:4/4d/Domino%27s_Pizza_Lobby_Entrance_Domino%27s_Farms_Ann_Arbor_Township_Michigan.JPG"],["Q847743",274,"restauration","Dunkin'","PC","Dunkin', anciennement connu sous le nom Dunkin' Donuts, littéralement « Les beignets pour faire trempette », est une multinationale américaine de la restauration rapide, spécialisée dans la vente de café et de beignets.",116,"fr:Dunkin'","c:e/e8/A_Dunkin%27_Donuts_restaurant_in_Hiawassee%2C_Georgia%2C_United_States_01.jpg"],["Q1131810",275,"restauration","Five Guys","C","Five Guys Enterprises, LLC est une chaîne américaine de restauration rapide spécialisée dans les hamburgers, les hot-dogs et les frites. La chaîne a son siège à Lorton, Virginie.",112,"fr:Five_Guys","c:d/d5/Five_Guys%2C_Merritt_Island.JPG"],["Q3136174",276,"restauration","Hippopotamus","C","Hippopotamus est une chaîne de restaurants à viande créée en 1968. Essentiellement présente en France, elle appartient au groupe Flo, détenu en majorité par le groupe Bertrand. La chaîne est exploitée par la société Hippo Gestion.","Hippopotamus est une chaîne de restaurants à viande créée en 1968.","fr:Hippopotamus_(restaurant)","c:e/ea/Hippopotamus_Montparnasse_Paris_2018_-%C2%AEYann_Deret-8467.jpg"],["Q524757",277,"restauration","KFC","R","KFC ou PFK au Québec et au nord du Nouveau-Brunswick, est une chaîne de restauration rapide américaine.",null,"fr:Kentucky_Fried_Chicken","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a3/Logo_KFC_%282026%29.svg/330px-Logo_KFC_%282026%29.svg.png"],["Q1192805",278,"restauration","Krispy Kreme","C","Krispy Kreme Doughnuts, Inc. est une chaîne de restaurants américaine spécialisée dans la fabrication et la vente de doughnuts. Elle est fondée en 1937 par Vernon Rudolph à Winston-Salem, en Caroline du Nord, où se situe toujours son siège social.","Krispy Kreme Doughnuts, Inc.","fr:Krispy_Kreme","c:2/21/Krispy_kreme_assort.JPG"],["Q38076",279,"restauration","McDonald's","E","McDonald's Corporation est une multinationale américaine de la restauration rapide dont le siège se situe à Chicago. Elle est fondée par Ray Kroc en 1955 après le rachat des droits d'une chaîne de restaurants exploitée par Richard et Maurice McDonald.","McDonald's Corporation est une multinationale américaine de la restauration rapide dont le siège se situe à Chicago.","fr:McDonald's","https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/McDonald%27s_Golden_Arches.svg/330px-McDonald%27s_Golden_Arches.svg.png"],["Q28494040",280,"restauration","O'Tacos","C","O'Tacos est une chaîne de restauration rapide française créée en 2010 mais trouvant ses origines en 2007 à Grenoble, puis à Bordeaux. L'enseigne est spécialisée dans les tacos français. Assumant les multiples accusations de malbouffe, la marque se développe par franchise, majoritairement en France, mais également à l'étranger.",116,"fr:O'Tacos","c:6/65/Haguenau_o%27tacos_rue_du_kestlerhof.jpg"],["Q3370417",281,"restauration","Paul","C","Paul est une marque française de magasins, de restaurants et de salons de thé proposant pains, viennoiseries, pâtisseries, sandwichs, salades et snacks.",109,"fr:Paul_(entreprise)","c:0/0f/Logo_Paul.png"],["Q191615",282,"restauration","Pizza Hut","PC","Pizza Hut est une chaîne de restauration rapide spécialisée dans la préparation et livraison de pizzas.",null,"fr:Pizza_Hut","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Pizza_Hut_2025.svg/330px-Pizza_Hut_2025.svg.png"],["Q1330910",283,"restauration","Popeyes","PC","Popeyes Louisiana Kitchen est une chaîne de restauration rapide américaine servant du poulet frit. Elle est propriété du groupe canadien Restaurant Brands International depuis 2017 et qui détient également Burger King et Tim Hortons.","Popeyes Louisiana Kitchen est une chaîne de restauration rapide américaine servant du poulet frit.","fr:Popeyes_Louisiana_Kitchen","c:6/66/Popeyes_Louisiana_Kitchen_%2851195358373%29.jpg"],["Q2109109",284,"restauration","Pret A Manger","C","Pret A Manger, aussi appelé Pret, est une entreprise de restauration rapide britannique spécialisée dans la conception et la vente de sandwichs et de salades. Pret est une filiale du groupe allemand JAB Holdings Company.",118,"fr:Pret_A_Manger","c:7/7f/Pret_a_Manger_%286387745805%29.jpg"],["Q286494",285,"restauration","Quick","C","Quick est une chaîne de restauration rapide dont le siège se situe à Aubervilliers et à Wilrijk. Fondée en Belgique en 1971, elle s'est implantée en France en 1980 et y a développé le cœur de son activité.","Quick est une chaîne de restauration rapide dont le siège se situe à Aubervilliers et à Wilrijk.","fr:Quick_(restauration)","c:d/d6/Quick_2023_logo.webp"],["Q37158",286,"restauration","Starbucks","R","Starbucks Corporation est une chaîne de cafés américaine. Fondée à Seattle en 1971 par Jerry Baldwing, Zev Siegl et Gordon Bowker, l'entreprise adopte le nom « Starbucks » en 1987 après son acquisition par Howard Schultz.","Starbucks Corporation est une chaîne de cafés américaine.","fr:Starbucks","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d3/Starbucks_Corporation_Logo_2011.svg/330px-Starbucks_Corporation_Logo_2011.svg.png"],["Q244457",287,"restauration","Subway","PC","Subway est une chaîne de restauration rapide américaine sous franchise, vendant principalement des sandwichs et des salades. « Subway » est un jeu de mots en référence à submarine sandwich, le pain ressemblant à un sous-marin et signifiant aussi métro en anglais.",115,"fr:Subway_(restauration)","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Subway_2016_logo.svg/330px-Subway_2016_logo.svg.png"],["Q752941",288,"restauration","Taco Bell","PC","Taco Bell est une chaîne américaine de restauration rapide, division du groupe Yum! Brands et leader mondial dans le secteur des restaurants à thème Tex-Mex.","Taco Bell est une chaîne américaine de restauration rapide, division du groupe Yum!","fr:Taco_Bell","c:8/8d/Tacobellsunnyvale.jpg"],["Q175106",289,"restauration","Tim Hortons","PC","Tim Hortons est une chaîne de restaurants rapides canadienne fondée en 1964 à Hamilton, en Ontario, par l'homme d'affaires Ron Joyce et le joueur de hockey Tim Horton. Son siège social est à Toronto.",111,"fr:Tim_Hortons","c:6/64/Tim_Hortons_in_Winnipeg%2C_MB%2C_Canada.jpg"],["Q550258",290,"restauration","Wendy's","PC","Wendy's est une chaîne américaine de restauration rapide fondée le 15 septembre 1969, à Columbus, par l'homme d'affaires Dave Thomas.",109,"fr:Wendy's","https://upload.wikimedia.org/wikipedia/fr/thumb/4/41/Wendy_s_2012_%28logo%29.svg/330px-Wendy_s_2012_%28logo%29.svg.png"],["Q2634111",291,"distribution","Action","C","Action est une chaîne de magasins hard-discount créée en 1993 aux Pays-Bas et présente également dans une quinzaine de pays européens à travers plus de deux mille points de vente. Son offre de produits est essentiellement fondé sur le non-alimentaire à bas prix.",118,"fr:Action_(enseigne)","c:9/97/Action_Hoorn_Ramen_31.jpg"],["Q125054",292,"distribution","Aldi","R","Aldi est une chaîne de supermarchés hard-discount allemande.",null,"fr:Aldi","c:d/dc/ALDI_Woerden_02.JPG"],["Q29904317",293,"distribution","AliExpress","PC","AliExpress est un site chinois de commerce en ligne du groupe Alibaba spécialisé dans la vente de produits à prix bas aux particuliers dans le monde. Ce site est né en 2010 de la volonté d'Alibaba de créer l'équivalent en anglais et à vocation internationale de son site en langue chinoise Taobao, réservé à la Chine. Le président d'AliExpress est Jack Ma. La maison mère d'AliExpress est basée en Chine, à Hangzhou, dans la province de Zhejiang.",117,"fr:AliExpress","c:1/1b/Aliexpress_in_Katowice%2C_Poland%2C_2020.jpg",{"cats":["marques","web"]}],["Q758603",294,"distribution","Auchan","C","Auchan est une multinationale française de grande distribution, fondée par Gérard Mulliez le 6 juillet 1961 et gérée par l'association familiale Mulliez.",116,"fr:Auchan","c:2/22/Auchan%2C_Le_Pontet%2C_Vaucluse%2C_France.jpg"],["Q2921695",295,"distribution","Boulanger","C","Boulanger est une entreprise française spécialisée dans le loisir, l'électronique grand public et l'électroménager, créée en 1954 par les frères Bernard et Gustave Boulanger.",115,"fr:Boulanger_(entreprise)","c:d/d0/Magasin_Boulanger_Colmar.jpg"],["Q740553",296,"distribution","Bpost","C","Bpost est une société anonyme belge de droit public qui a deux grandes activités:",null,"fr:Bpost","https://upload.wikimedia.org/wikipedia/fr/thumb/3/39/Bpost_2010_%28logo%29.svg/330px-Bpost_2010_%28logo%29.svg.png"],["Q217599",297,"distribution","Carrefour","PC","Carrefour est initialement une enseigne d'hypermarchés créée à Annecy en France, faisant partie du groupe Carrefour créé en 1959.",115,"fr:Carrefour_(enseigne)","https://upload.wikimedia.org/wikipedia/fr/thumb/3/3b/Logo_Carrefour.svg/330px-Logo_Carrefour.svg.png"],["Q966971",298,"distribution","Castorama","C","Castorama est une entreprise de grande distribution de bricolage, de décoration et d'aménagement de la maison, jadis française, devenue filiale de la société britannique Kingfisher en 2002. L’enseigne est un des principaux acteurs du secteur, avec plus de 100 points de vente en France. Elle occupe, en 2023, le deuxième rang des enseignes de bricolage en termes de chiffre d'affaires.",116,"fr:Castorama","c:3/38/Castorama_%28Stettin%29.jpg"],["Q16033266",299,"distribution","Colruyt","C","Colruyt est un nom de famille néerlandophone.",null,"fr:Colruyt",""],["Q715583",300,"distribution","Costco","R","Costco Wholesale Corporation ou Costco est une entreprise américaine de grande distribution fonctionnant sur le principe de libre-service de gros avec adhésion.",111,"fr:Costco","c:7/7d/Costcoheadquarters.jpg"],["Q14903417",301,"distribution","Delhaize","C","Le groupe Delhaize était un groupe de distribution international belge, actif dans 11 pays. Le groupe Delhaize a été fondé en Belgique en 1867 par Jules Delhaize, il a fusionné en 2016 avec le néerlandais Ahold pour former Ahold Delhaize.","Le groupe Delhaize était un groupe de distribution international belge, actif dans 11 pays.","fr:Groupe_Delhaize","c:6/69/20170402_seraing_boncelles07.jpg"],["Q489815",302,"distribution","DHL","PC","DHL est une entreprise allemande d'origine américaine de transport de colis et courriers fondée en 1969 à San Francisco, aux États-Unis et détenue depuis 2002 par la Deutsche Post, renommée DHL Group en 2023. DHL est une grande entreprise de logistique mondiale et opère dans 220 pays et territoires. DHL déclare transporter 1,614 milliard de colis chaque année et dispose d’environ 600 000 employés et cadres, répartis dans le monde.",109,"fr:DHL_(entreprise)","c:9/9e/Post_Tower_Bonn_2009-06-25.jpg"],["Q459477",303,"distribution","FedEx","PC","FedEx Corporation est une entreprise américaine et compagnie aérienne spécialisée dans le transport international de fret, basée à Memphis, dans le Tennessee. Son nom est l'abréviation syllabique de Federal Express, appellation qu'elle utilise officiellement de 1973 à 1994.",116,"fr:FedEx","c:7/7e/FedEx_Super_Hub_~%60_27_-_panoramio.jpg"],["Q676585",304,"distribution","Fnac","C","La Fédération nationale d'achats des cadres, ou Fnac, est une chaîne de magasins française spécialisée dans la distribution de produits culturels et électroniques. À destination du grand public, la gamme s'est élargie en 2012 au petit électroménager, déjà présent à la création de l'enseigne et abandonné dans les années 1970.",110,"fr:Fnac","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Fnac_Logo.svg/330px-Fnac_Logo.svg.png"],["Q3094686",305,"distribution","Galeries Lafayette","C","Les Galeries Lafayette sont une enseigne de grands magasins appartenant au groupe Galeries Lafayette qui est membre de l'Association Internationale des Grands Magasins depuis 1960.",118,"fr:Galeries_Lafayette","https://upload.wikimedia.org/wikipedia/fr/thumb/7/7f/GaleriesLafayettelogo.jpg/330px-GaleriesLafayettelogo.jpg"],["Q332474",306,"distribution","Harrods","PC","Harrods est un grand magasin de luxe, situé sur Brompton Road dans le quartier de Knightsbridge, à Londres.",null,"fr:Harrods","c:6/67/HarrodsDay.jpg"],["Q903805",307,"distribution","HEMA","C","HEMA est une chaîne de magasins néerlandaise. Elle se spécialise dans les articles pour la maison à bas prix, lesquels sont fabriqués pour la chaîne, même dans des pays à bas coûts.","HEMA est une chaîne de magasins néerlandaise.","fr:HEMA","https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/HEMA_Logo.svg/330px-HEMA_Logo.svg.png"],["Q54078",308,"distribution","Ikea","R","Ikea, stylisé IKEA, est une entreprise d'origine suédoise dont le siège social se trouve à Delft aux Pays-Bas, spécialisée dans la conception et la vente de détail de mobilier et objets de décoration prêts à poser ou en kit à assembler.",110,"fr:Ikea","c:1/16/Ashton-u-Lyne-IKEA1.jpg"],["Q3153200",309,"distribution","Intermarché","C","Intermarché est une enseigne française de grande distribution alimentaire du Groupement Mousquetaires fondée le 15 septembre 1969, sous l'enseigne EX - Offices de distribution par Jean-Pierre Le Roch. Par la suite, les EX deviendront, en 1973, Intermarché.",114,"fr:Intermarché","c:d/da/Civens_-_Supermarch%C3%A9_Intermarch%C3%A9_%28juin_2023%29.jpg"],["Q2226366",310,"distribution","Kruidvat","C","Kruidvat est une chaîne de drogueries belgo-néerlandaise créée en 1975 et appartenant au groupe A.S. Watson.","Kruidvat est une chaîne de drogueries belgo-néerlandaise créée en 1975 et appartenant au groupe A.S.","fr:Kruidvat","c:5/51/Kruidvat.jpg"],["Q373724",311,"distribution","La Poste","C","La Poste est une société anonyme française majoritairement présente en tant qu'opérateur de services postaux, de services bancaires et assurantiels, opérateur de téléphonie mobile, fournisseur de services numériques et de solutions commerce, commerce en ligne et de collecte et vente de données. La Poste est majoritairement détenue par la Caisse des dépôts et consignations et de manière minoritaire, par l'État français. La Poste et toutes ses filiales regroupées forment le groupe La Poste.",112,"fr:La_Poste_(entreprise_française)","c:b/b1/Patio%2C_poste_centrale_du_Louvre.jpg"],["Q1200698",312,"distribution","Le Bon Marché","C","Le Bon Marché est un grand magasin français, situé dans un quadrilatère encadré par la rue de Sèvres, la rue de Babylone, la rue du Bac et la rue Velpeau dans le 7e arrondissement de Paris. Il s'appelle Au Bon Marché pendant 151 ans, jusqu'en 1989.",111,"fr:Le_Bon_Marché","https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Le-bon-marche-logo-vector.svg/330px-Le-bon-marche-logo-vector.svg.png"],["Q6511801",313,"distribution","Leclerc","C","E.Leclerc est une enseigne française de grande distribution fondée par Édouard Leclerc en 1949, l'un des leaders des supermarchés en France.","","fr:Leclerc",""],["Q889624",314,"distribution","Leroy Merlin","PC","Leroy Merlin est une enseigne française de grande distribution spécialisée dans l'amélioration de l'habitat. Fondée par la famille Leroy Merlin et rachetée en 1981 par la famille Mulliez, elle a été intégrée au groupe Adeo, propriété de la même famille, dont elle est l’enseigne pionnière et la plus importante en France. Cette enseigne est dédiée aux grandes surfaces de bricolage.","Leroy Merlin est une enseigne française de grande distribution spécialisée dans l'amélioration de l'habitat.","fr:Leroy_Merlin","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Leroy_Merlin_-_logo_%28France%2C_1995-%29.svg/330px-Leroy_Merlin_-_logo_%28France%2C_1995-%29.svg.png"],["Q151954",315,"distribution","Lidl","R","Lidl est une entreprise de distribution allemande de \"soft discount\" fondée en 1930 par Josef Schwarz. En 2021, le groupe est présent dans 26 pays en Europe avec 11 463 magasins dont 3 277 en Allemagne. Lidl, dont le siège est à Neckarsulm en Allemagne, est une filiale du groupe Schwarz, détenu par Dieter Schwarz.","Lidl est une entreprise de distribution allemande de \"soft discount\" fondée en 1930 par Josef Schwarz.","fr:Lidl","c:d/df/Somain_-_Lidl_%2801%29.JPG"],["Q3321241",316,"distribution","Monoprix","C","Monoprix est une entreprise française appartenant au secteur du commerce et de la distribution, fondée le 29 octobre 1932. Essentiellement implantée en centre-ville, Monoprix est à l’origine du retour des formats de proximité en France avec son enseigne « Monop’ ». Elle joue avec une image citadine, voire « d'épicerie fine parisienne ». Son nom est formé du préfixe « mono- » et du mot « prix ».",116,"fr:Monoprix_(France)","c:d/d2/Monoprix%2C_Caen_2025-03-29.jpg"],["Q3382454",317,"distribution","Picard Surgelés","C","Picard Surgelés, ou simplement Picard, est une entreprise française spécialisée dans le commerce de détail de produits alimentaires surgelés sous marque de distributeur. Elle est le leader français dans ce secteur, contrôlant près de 20 % du marché en 2021.",118,"fr:Picard_Surgelés","c:7/7d/Picard_Surgel%C3%A9s_Logo26.png"],["Q2670967",318,"distribution","Plesio","C","Le groupe Plesio est une entreprise française de grande distribution, fondée le 2 août 1898 par Geoffroy Guichard, sous la raison sociale Guichard-Perrachon & Cie. Son siège social est à Saint-Étienne.",119,"fr:Plesio_(entreprise)","c:e/eb/Entr%C3%A9e_du_si%C3%A8ge_social_de_Casino.jpg"],["Q2529029",319,"distribution","Système U","C","Coopérative U est une coopérative de commerçants de grande distribution française présidée par Dominique Schelcher.",null,"fr:Coopérative_U","https://upload.wikimedia.org/wikipedia/fr/thumb/1/13/U_commer%C3%A7ants_logo_2018.svg/330px-U_commer%C3%A7ants_logo_2018.svg.png"],["Q696334",320,"distribution","Toys “R” Us","C","Toys “R” Us est une chaîne de magasins de jouets créée aux États-Unis en 1948.",null,"fr:Toys_“R”_Us","c:1/14/Toysrus_Us.jpg"],["Q226146",321,"distribution","UPS","C","Le sigle UPS désigne notamment:",null,"fr:UPS",""],["Q483551",322,"distribution","Walmart","E","Walmart Inc. est une multinationale américaine spécialisée dans la grande distribution, fondée par Sam Walton. Lancée en 1962, l'entreprise s'est développée en Arkansas, avant de dominer le marché américain et commencer à s'internationaliser en 1991.","Walmart Inc.","fr:Walmart","c:4/47/Walmart_7.jpg"],["Q136570",323,"distribution","Zalando","C","Zalando est une entreprise de commerce en ligne allemande, spécialisée dans la vente de chaussures et de vêtements, basée à Berlin. Créée en 2008 par Rocket Internet, elle est présente dans 23 pays européens.",115,"fr:Zalando","c:d/dd/Zalando_Turm_01.jpg"],["Q159433",324,"loisirs","3M","PC","3M Company, auparavant Minnesota Mining and Manufacturing Company, est un conglomérat américain basé à Saint Paul. Pour le grand public, la société est connue pour quelques-unes de ses marques comme Scotch, créée dans les années 1920, ou Post-it, lancée dans les années 1980.","3M Company, auparavant Minnesota Mining and Manufacturing Company, est un conglomérat américain basé à Saint Paul.","fr:3M","https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/3M_wordmark.svg/330px-3M_wordmark.svg.png"],["Q212599",325,"loisirs","Accor","PC","Accor est un groupe hôtelier français fondé en 1967 par Gérard Pélisson et Paul Dubrule qui possède, gère et franchise des hôtels, des stations touristiques et des résidences de vacances.",118,"fr:Accor","https://upload.wikimedia.org/wikipedia/fr/thumb/c/c3/Accor_Logo.png/330px-Accor_Logo.png"],["Q131005",326,"loisirs","Air France","PC","Air France est la compagnie aérienne nationale française, fondée le 30 août 1933 et inaugurée le 7 octobre de la même année. Membre du Groupe Air France-KLM, ses activités principales sont le transport de passagers, de fret ainsi que la maintenance et l'entretien des avions.",117,"fr:Air_France","c:b/bc/Air_France_Airbus_A350-900_F-HUVM_on_final_approach_to_Boston_July_2026_1_%28cropped%29.jpg",{"cats":["marques","transports"]}],["Q2311",327,"loisirs","Airbus","R","Le groupe Airbus SE est un groupe européen actif dans l'industrie et le secteur aéronautique et spatial, tant civil que militaire. Ses sièges sociaux sont situés à Blagnac en France et à Leyde aux Pays-Bas. Il regroupe de nombreuses entreprises internationales avec des lieux de production situés essentiellement en France, en Allemagne, en Espagne et au Royaume-Uni. Ses filiales les plus notoires sont Airbus Commercial Aircraft, Airbus Defence and Space et Airbus Helicopters.",119,"fr:Airbus_(société)","c:6/60/Airbus_Industrie_A321neo_D-AVXA_%2829428329122%29.jpg"],["Q167447",328,"loisirs","Barbie","PC","Barbie est une poupée mannequin de 29 cm commercialisée depuis 1959 par Mattel, une société américaine de jouets et de jeux. Elle reprenait la forme adulte, les cheveux blonds et le principe de Bild Lilli, première poupée mannequin lancée en Allemagne un peu plus tôt.",118,"fr:Barbie_(poupée)","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Barbie_Logo.svg/330px-Barbie_Logo.svg.png",{"cats":["marques","enfance"]}],["Q795981",329,"loisirs","Bic","C","BIC est un groupe français fondé le 25 octobre 1945 par Marcel Bich.",null,"fr:Bic_(entreprise)","c:e/e1/03-BICcristal2008-03-26.jpg"],["Q66",331,"loisirs","Boeing","R","The Boeing Company ou Boeing est un constructeur aéronautique et aérospatial américain fondé en 1916 par William Boeing et George Conrad Westervelt. Son siège social est situé à Arlington en Virginie et sa plus grande usine à Everett, près de Seattle dans l'État de Washington.",119,"fr:Boeing","c:b/b1/Boeing_Everett_Plant.jpg",{"cats":["marques","transports"]}],["Q152057",332,"loisirs","BP","R","La société BP est une compagnie britannique de recherche, d'extraction, de raffinage et de vente de pétrole fondée en 1909, anciennement nommée Anglo-Persian Oil Company, puis Anglo-Iranian Oil Company, puis British Petroleum Company, puis BPAmoco, avant d'être renommée BP.",117,"fr:BP_(entreprise)","https://upload.wikimedia.org/wikipedia/fr/thumb/3/32/B_P.svg/330px-B_P.svg.png"],["Q1076645",334,"loisirs","Club Med","C","Club Med, anciennement Club Méditerranée depuis sa création sous forme d'association, est une entreprise française, créée en 1950 par le Belge Gérard Blitz, qui commercialise principalement des séjours dans des villages de vacances dans le monde entier. Depuis 2015, le Club Med appartient au conglomérat chinois Fosun International.",115,"fr:Club_Med",""],["Q341456",335,"loisirs","Colgate","C","Colgate est un nom et toponyme pouvant désigner:",null,"fr:Colgate",""],["Q858702",338,"loisirs","Duracell","C","Duracell est une marque américaine de piles électriques créée en 1964, et de lampes de poche, appartenant depuis 2016 à la société d'investissement Berkshire Hathaway de Warren Buffett.",119,"fr:Duracell","c:e/e8/Duracell_battery.jpg"],["Q191551",339,"loisirs","EasyJet","PC","EasyJet est une compagnie aérienne à bas prix britannique. Au 1er juillet 2015, elle est la deuxième compagnie européenne en nombre de passagers transportés après Ryanair.","EasyJet est une compagnie aérienne à bas prix britannique.","fr:EasyJet","c:7/7a/Airbus_A320-200_of_EasyJet_%28G-EZOW%29_lands_at_Bristol_Airport%2C_England_15Aug2016_arp.jpg",{"cats":["marques","transports"]}],["Q1200840",340,"loisirs","Energizer","C","Energizer Holdings est une entreprise américaine possédant les marques de piles Energizer, de rasoirs Wilkinson Sword et les produits d'hygiène Playtex.",117,"fr:Energizer","c:e/ed/Energizer_Holdings_in_Town_and_Country_-_2013.jpg"],["Q156013",341,"loisirs","Eurostar","PC","Eurostar International Ltd est une entreprise ferroviaire franco-britannique, qui exploite depuis 1994 les trains à grande vitesse reliant Paris, ainsi que Bruxelles et Amsterdam, à Londres, en empruntant le tunnel sous la Manche. On appelle également Eurostar les trains à grande vitesse utilisés par l'entreprise: les rames TGV TMST, mais également les Eurostar e320.",115,"fr:Eurostar","c:7/7c/Eurostars.jpg",{"cats":["marques","transports"]}],["Q503592",343,"loisirs","Gillette","C","Gillette est une marque américaine de rasoirs fondée en 1901 par King C. Gillette, inventeur du rasoir à lames jetables.","","en:Gillette",""],["Q1168517",344,"loisirs","Groupe SEB","C","Le Groupe SEB, officiellement SEB SA, est une société française, numéro un mondial dans le domaine du petit équipement domestique.",118,"fr:Groupe_SEB","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Seb_industrial_location.svg/330px-Seb_industrial_location.svg.png"],["Q501476",346,"loisirs","Hasbro","PC","Hasbro est une société américaine spécialisée dans les jouets et les jeux qui est créée en 1923 par les frères Henry et Hillel Hassenfeld à Providence. Hasbro est la contraction de « Hassenfeld Brothers ».",119,"fr:Hasbro","https://upload.wikimedia.org/wikipedia/fr/thumb/e/ea/Hasbro_logo.svg/330px-Hasbro_logo.svg.png"],["Q191794",347,"loisirs","Hello Kitty","R","Hello Kitty est un personnage fictif, et l'un des nombreux personnages créés par la société japonaise Sanrio. Les produits Hello Kitty utilisent généralement des couleurs rose vif et sont reconnaissables par le logo représentant une petite fille aux traits de chat avec un ruban rouge sur la tête. Le copyright date de 1976 et Hello Kitty est maintenant une marque déposée.","Hello Kitty est un personnage fictif, et l'un des nombreux personnages créés par la société japonaise Sanrio.","fr:Hello_Kitty","c:0/09/HK_SYP_Sai_Ying_Pun_%E9%A6%99%E6%B8%AF%E5%95%86%E6%A5%AD%E4%B8%AD%E5%BF%83_Hong_Kong_Plaza_%E6%97%A5%E6%9C%AC%E4%B8%80%E7%94%B0%E7%99%BE%E8%B2%A8%E5%BA%97_YATA_department_Store_March_2017_Lnv2_Hello_Kitty_02.jpg",{"cats":["marques","enfance"]}],["Q585537",348,"loisirs","Hot Wheels","PC","Hot Wheels est une marque de jouets américaine fondée en 1968 appartenant au groupe Mattel et produisant des voitures miniatures.",117,"fr:Hot_Wheels","c:e/e6/2011_Greater_Los_Angeles_Auto_Show_IMG_4308_%287016901789%29.jpg",{"cats":["marques","enfance"]}],["Q2766",349,"loisirs","iPhone","E","L'iPhone, prononcé en français, est une gamme de smartphones créée par Apple comprenant plusieurs générations, opérant sur le système d'exploitation mobile iOS, développé également par Apple. Steve Jobs dévoile le premier iPhone, l'iPhone 2G, le 9 janvier 2007. Chaque année, la firme américaine publie de nouveaux modèles ainsi que des mises à jour du système d'exploitation.",118,"fr:IPhone","c:f/f9/IPhone_17_launch_at_Apple_TRX_Malaysia_80.jpg",{"cats":["marques","sciences","tech"]}],["Q170484",352,"loisirs","Lego","R","Lego est une gamme de jouets de construction fabriqués par le groupe danois The Lego Group, une société privée basée à Billund. Elle se compose de briques en plastique emboîtables, de figurines et de diverses autres pièces. Les briques Lego de différentes couleurs en acrylonitrile butadiène styrène peuvent être assemblées et reliées afin de construire des objets tels que des véhicules, des bâtiments, des robots fonctionnels, des paysages, des tableaux, etc.",118,"fr:Lego","https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/LEGO_logo.svg/330px-LEGO_logo.svg.png",{"cats":["marques","enfance"]}],["Q1200552",353,"loisirs","Marvel Entertainment","C","Marvel Entertainment, Inc. est un grand groupe de médias américain qui est né du rapprochement du Marvel Entertainment Group et du fabricant de jouets Toy Biz dans les années 1990. L'histoire de Marvel débute dans les années 1930 comme éditeur et reste sur ce cœur de métier jusqu'en 1990 quand Ronald Perelman diversifie la société. Depuis 2009, Marvel est devenu une filiale de la Walt Disney Company, qui distribue dès lors les productions de l'Univers cinématographique Marvel au succès international.","Marvel Entertainment, Inc.","fr:Marvel_Entertainment","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Marvel_Logo.svg/330px-Marvel_Logo.svg.png"],["Q596139",354,"loisirs","Mattel","R","Mattel Inc. est une société américaine spécialisée dans les jouets et jeux, fondée en 1945 par Harold « Matt » Matson, Elliot Handler et Ruth Handler. Elle est le second fabricant mondial derrière Lego. Elle fabrique la plupart de ses jouets en Chine.","Mattel Inc.","fr:Mattel","https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Mattel_%282019%29.svg/330px-Mattel_%282019%29.svg.png"],["Q1891883",358,"loisirs","Nerf","C","Nerf est une marque américaine de jouets blasters créée en 1969 par Reyn Guyer et Parker Brothers, détenue depuis 1991 par la société Hasbro. La majorité des jouets sont des armes factices, dénommés « blasters », mais Nerf produit aussi des ballons en mousse et en caoutchouc. Les jouets les plus connus sont des pistolets/fusils qui tirent des projectiles en mousse, en gomme, ou en gel, sous forme de fléchettes ou de billes. Il existe d'autres marques de ce genre, mais Nerf est le numéro 1 mondial.",118,"fr:Nerf_(marque)","c:e/e3/Nerf_orange_logo.png"],["Q2340498",361,"loisirs","Pampers","C","La marque Pampers est une marque américaine de produits pour nourrissons.",null,"fr:Pampers","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b9/Logo_Pampers.svg/330px-Logo_Pampers.svg.png"],["Q159846",362,"loisirs","Paramount Pictures","E","Paramount Pictures Corporation, plus connue sous le nom de Paramount Pictures, est une des plus grandes sociétés américaines de production cinématographique.",112,"fr:Paramount_Pictures","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Paramount_Pictures_with_Skydance_byline.svg/330px-Paramount_Pictures_with_Skydance_byline.svg.png"],["Q1431285",363,"loisirs","Pierre & Vacances","C","Le groupe Pierre & Vacances-Center Parcs est un groupe français du secteur des résidences de tourisme fondé en 1967 par Gérard Brémond. Sa croissance repose sur le fait d'associer l'immobilier et le tourisme.",119,"fr:Groupe_Pierre_&_Vacances-Center_Parcs","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Pierre_%26_Vacances_logo.svg/330px-Pierre_%26_Vacances_logo.svg.png"],["Q160719",365,"loisirs","Playmobil","C","Playmobil est une marque allemande de jouets créée en 1974 par Hans Beck et Horst Brandstätter. Le nom Playmobil vient de l'anglais play et mobil.","Playmobil est une marque allemande de jouets créée en 1974 par Hans Beck et Horst Brandstätter.","fr:Playmobil","https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Playmobil_logo.svg/330px-Playmobil_logo.svg.png",{"cats":["marques","enfance"]}],["Q864",366,"loisirs","Pokémon","M","Pokémon est une franchise créée par Satoshi Tajiri en 1995, présente en particulier en jeu vidéo, dans des séries éditées par Nintendo. Selon les statistiques de Nintendo en 2010, les jeux Pokémon se sont vendus à environ 250 millions d’unités. Le jeu vidéo Pokémon Rouge et Bleu s’est vendu à plus de 30 millions d’exemplaires, ce qui en fait un record des ventes dans l’histoire du jeu vidéo.",113,"fr:Pokémon","https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/International_Pok%C3%A9mon_logo.svg/330px-International_Pok%C3%A9mon_logo.svg.png",{"cats":["marques","pokemon"]}],["Q212405",368,"loisirs","Procter & Gamble","PC","Procter & Gamble est une multinationale américaine spécialisée dans les produits de nettoyage, d'hygiène et de pharmacie. Elle est cotée à la bourse de New York.",110,"fr:Procter_&_Gamble","https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Procter_%26_Gamble_logo.svg/330px-Procter_%26_Gamble_logo.svg.png"],["Q170614",370,"loisirs","Ryanair","E","Ryanair est une compagnie aérienne à bas prix irlandaise fondée en 1984 dont le siège social est situé à Swords.",null,"fr:Ryanair","c:e/e8/Ryanair%2C_EI-DWK%2C_Boeing_737-8AS_%2816237619133%29.jpg",{"cats":["marques","transports"]}],["Q154950",371,"loisirs","Shell","R","Shell est une compagnie pétrolière britannique, l'une des plus importantes sociétés multinationales.",null,"fr:Shell_(entreprise)","c:1/1b/The_Shell_Centre_%288709496019%29.jpg"],["Q13646",372,"loisirs","SNCF","PC","La Société nationale des chemins de fer français — usuellement appelée la SNCF — est l'entreprise ferroviaire publique française, créée le 1er janvier 1938 par convention entre l'État et les compagnies de chemin de fer préexistantes, en application du décret-loi du 31 août 1937.",118,"fr:Société_nationale_des_chemins_de_fer_français","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a1/Logo_SNCF_%282011%29.svg/330px-Logo_SNCF_%282011%29.svg.png",{"cats":["marques","transports"]}],["Q466985",375,"loisirs","Thalys","C","Thalys est, de 1995 à 2023, le nom commercial d'un service de trains à grande vitesse entre la France, la Belgique, l'Allemagne et les Pays-Bas autour de l'axe Paris – Bruxelles. Il est exploité par l'opérateur THI Factory, dont le capital est détenu en totalité par Eurostar Group.",115,"fr:Thalys","c:f/f8/Twee_Thalys-treinen_op_Amsterdam_Centraal.jpg",{"cats":["marques","transports"]}],["Q154037",377,"loisirs","TotalEnergies","PC","TotalEnergies SE, ancienne Compagnie française des pétroles, puis Total, est une multinationale française de production et de fourniture d’hydrocarbures et d’autres sources d’énergies: pétrole et biocarburants, gaz naturel et gaz verts, énergies renouvelables et électricité.",119,"fr:TotalEnergies","https://upload.wikimedia.org/wikipedia/fr/thumb/f/f7/Logo_TotalEnergies.svg/330px-Logo_TotalEnergies.svg.png"],["Q1129117",378,"loisirs","Tupperware","C","Tupperware Brands Corporation est une firme transnationale américaine produisant des boîtes en plastique et d'autres ustensiles de cuisine, la plupart fabriqués à l'aide d'un procédé d'injection plastique. La société fut fondée en 1946 par l'ingénieur américain Earl Tupper, inventeur du bol hermétique en polyéthylène. La firme a développé un type de vente particulier: la « démonstration-vente à domicile ».",116,"fr:Tupperware","c:f/f9/Tupperware_party.jpg"],["Q157062",379,"loisirs","Unilever","PC","Unilever est une multinationale anglo-néerlandaise, dont le siège social est situé à Londres et à Rotterdam.",null,"fr:Unilever","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b3/Logo_Unilever_2024.svg/330px-Logo_Unilever_2024.svg.png"],["Q168383",380,"loisirs","Universal Pictures","E","Universal Pictures est une société de production cinématographique américaine appartenant à Comcast, au sein de sa filiale NBCUniversal.",114,"fr:Universal_Pictures","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Universal_Pictures_logo.svg/330px-Universal_Pictures_logo.svg.png"],["Q137691184",381,"loisirs","Warner Bros.","R","Warner Bros. est un grand studio de cinéma américain fondé en 1923 par les frères Warner, à l'origine des Looney Tunes, de Harry Potter et de Batman au cinéma.","","en:Warner_Bros.","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Warner_Bros._Discovery_%28symbol%29.svg/330px-Warner_Bros._Discovery_%28symbol%29.svg.png"],["Q205533",382,"loisirs","Zippo","C","Zippo est une marque américaine de briquets, créée en 1932 par George G. Blaisdell, fils de Philo Blaisdell, à Bradford, en Pennsylvanie. Le brevet fut déposé le 3 mars 1936. En 2018, Zippo est la propriété du petit-fils de George Blaisdell.","Zippo est une marque américaine de briquets, créée en 1932 par George G.","fr:Zippo","https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Zippo_logo.svg/330px-Zippo_logo.svg.png"]]]);